import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "synax-baramouda-1",
    title: { en: "Baramouda 1", ar: "1 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نياحة القديس سلوانس الراهب" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم تنيح الأب القديس سلوانس الراهب وقد ترهب هذا الطوباوي بدير القديس مقاريوس وسار في الفضيلة وأجهد نفسه بالصوم الطويل والسهر الكثير والأتساع والمحبة حتى سار أبا عظيما وقد أهله الله لرؤية المناظر الإلهية وكان يوصي تلاميذه دائما بأن لا يهملوا شغل اليد ,ان يتصدقوا بما يفضل عنهم وفي أحد الأيام رآه راهب كسلان منهمكا مع تلاميذه في عمل أيديهم فقال لهم لا تعملوا للطعام الفاني . فانه مكتوب : ان مريم اختارت لنفسها نصيبا صالحا لا ينزع منها &quot; فلما سمعه الشيخ قال لتلميذه &quot; أعط الأب كتابا وأدخله الكنيسة وأغلق عليه ليقرأ ولا تدع عنده شيئا يؤكل &quot; ففعل التلميذ ذلك . ولما أتت الساعة التاسعة أكل الشيخ وتلاميذه ولم يدعوا الراهب وفي أثناء ذلك كان الراهب شاخصا بعينيه نحو الباب منتظرا من يدعوه وإذ اشتد الجوع خرج من الكنيسة وقال للشيخ &quot; أما أكل الاخوة اليوم ؟ &quot; فأجابه &quot; نعم &quot; فلماذا لم تدعني للآكل معهم ؟ فأجابه &quot; أنت رجل لا حاجة بك إلى طعام جسدي ويكفيك النصيب الصالح . ولهذا نعمل بأيدينا &quot; فعلم الأخ أنه قد أخطأ فضرب مطانية مستغفرا فأجابه الشيخ قائلا &quot; يا ابني لا بد لمريم من أن تحتاج إلى مرثا لان بمرثا مدحت مريم &quot; فأنتفع الأخ من هذا التعليم وصار مداوما علي العمل بيديه متصدقا بما يفضل عنه ." } },
      { kind: 'reading', text: { en: "", ar: "وقد وضع هذا الأب أقوالا نافعة في الجهاد الروحي ولما أكمل جهاده بشيخوخة صالحة أعلمه الله تعالي بوقت نياحته فاستدعي الرهبان القريبين منه وتبارك منهم وسألهم أن يذكروه في صلاتهم ثم تنيح بسلام . صلاته تكون معنا ." } },
      { kind: 'heading', text: { en: "", ar: "نياحة هارون الكاهن" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم تنيح الصديق البار هارون أخو موسى أول أنبياء الشريعة وكان من سبط لآوى ، وقد اجري الله علي يديه آيات كثيرة بأرض مصر . وانتخبه هو وبنيه كهنة له وفرض لهم عشور بني إسرائيل مع القرابين ولما قام عليه بنو قورح أبادهم الله بأن أمر الأرض فابتلعتهم أحياء . وقد أرضي الله بحسن سيرته وحفظ شريعته وتنيح بسلام . ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "", ar: "غارة عربان الصعيد علي برية شيهيت" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم أغار عربان الصعيد علي برية القديس مقاريوس الكبير ونهبوا كل ما كان في الكنائس والأديرة فاجتمع الأباء الرهبان وصلوا وتشفعوا بالأباء القديسين فطردهم السيد المسيح ونجي الرهبان من أيديهم ." } },
      { kind: 'heading', text: { en: "The Martyrdom of the Holy Virgins: Agape, Eirene, and Shiona.", ar: "" } },
      { kind: 'reading', text: { en: "On this day the three holy virgins: Agape, Eirene, and Shiona (Susinia) were martyred. They were from Thessalonica, and worshipped Christ as their parents. They chose the life of chastity and they agreed to devote themselves to the ascetic life. They fasted and prayed unceasingly, visited the convents often and participated with the virgins in their prayers and asceticism. When Maximianus the infidel, reigned, he restored the worship of the idols and shed the blood of many Christians. These saints were afraid and they fled to the mountain and hid themselves in a cave devoting themselves to their worship and asceticism.", ar: "" } },
      { kind: 'reading', text: { en: "Every week, an aged Christian woman visited them bringing all things needed and took the work of their hands to sell it, and distributed the remainder as alms to the poor. One day a malicious person observed the frequent visits of this old woman to the mountain, he followed her secretly until he knew the cave that she entered. He hid himself so she did not see him on her way back, and he thought that she was hiding precious things in it. After she left the cave by a distance he entered the cave and he found the precious pearls the prides of the Christ standing praying. He bound them, dragged them away, and brought them to the Governor of Thessalonica. He asked them about their faith, they confessed that they were Christians worshipping that Who was Crucified. The Governor became wrath with them, tortured them much, then cast them into the fire, and they delivered up their souls and received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the One Hundred and Fifty believers by the hand of king of Persia.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the incident of the martyrdom of one hundred and fifty believers by the king of Persia. This king besieged Christian cities which were near the borders of his country, and captured many of them. When they refused to worship the sun and the stars, he commanded to cut off their heads, and they received the crowns of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-2",
    title: { en: "Baramouda 2", ar: "2 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس خرستوفورس" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديس خرستوفورس . وكان من البلاد التي يأكل أهلها لحوم البشر والذين آمنوا علي يد متياس الرسول - كما جاء في اليوم الثامن من شهر برمهات - وكان ذا هيئة بشعة وجسم كجسم الجبابرة ولكن نفسه كانت وديعة صالحة . ولما وقع أسيرا في يد جند داكيوس الملك الوثني أخذ يوبخ الجند علي تعذيبهم المسيحيين فضربه رئيس الجند فقال له : &quot; لولا وصية المسيح التي تعلمني ألا أقابل الإساءة بمثلها لما كنت أنت وعسكرك تحسبون شيئا أمامي &quot; فأرسل القائد إلى داكيوس يعرفه أمره . فأوفد مائتي جندي لإحضاره فحضر معهم وحدث – وهم في الطريق - أن الخبز فرغ منهم إلا قليل منه فصلي وبارك في هذا القليل فصار كثيرا فأكلوا متعجبين وآمنوا بالسيد المسيح اله خرستوفورس . ولما وصلوا إلى إنطاكية تعمدوا بيد الأنبا بولا البطريرك ولما مثل خرستوفورس أمام داكيوس ارتعب من هول منظره فلاطفه وخادعه وصرفه من أمامه . ثم أرسل إليه امرأتين جميلتين ليستميلاه إلى الخطية . فوعظهما القديس فآمنتا علي يديه بالسيد المسيح معترفين جهارا أمام الملك بأيمانهما بالسيد المسيح فأمر الملك بقطع رأسيهما ونالا إكليل الشهادة . أما هذا القديس فطرحوه في قدر كبير فوق نار متقدة فلم تمسه النار بأذى فتعجب الحاضرون وآمنوا بالسيد المسيح وتقدموا لاخراج القديس من القدر فأمر الملك بتقطيعهم بالسيوف . وأخيرا أمر بضرب عنقه ونال إكليل الشهادة . شفاعته تكون معنا . آمين ." } },
      { kind: 'heading', text: { en: "", ar: "نياحة البابا يوأنس التاسع البطريرك الواحد والثمانين" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم سنة 1043 ش 29 مارس سنة 1327 م تنيح البابا يوأنس التاسع البطريرك (81) وهو من ناحية نفيا منوفية ويعرف بيوأنس النقادي أحد الأخوين . وفي أيامه جرت شدائد كثيرة علي النصارى فمنهم من قتل ومن حرق ومن صلب وشهروا بهم علي الجمال وألبسوهم العمائم والثياب الزرقاء ، ثم تحنن الله علي الشعب برحمته . وتنيح البابا بحارة زويلة ودفن بدير النسطور بعد أن قام علي الكرسي ست سنين وستة شهور ويما واحدا لأنه تولي الكرسي في يوم أول بابه سنة 1037 ش ( 28 سبتمبر سنة 1321 م ) صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. James the Apostle Brother of St. John the Apostle.", ar: "" } },
      { kind: 'reading', text: { en: "On this day, St. James the Apostle, the son of Zebedee, and the brother of St. John, the Apostle, was martyred. After he had preached the Gospel in Judea and Samaria, he went to Spain. He preached the Gospel there, and its people believed in the Lord Christ. He returned to Jerusalem and pursued his ministry.", ar: "" } },
      { kind: 'reading', text: { en: "He always advised his flock to give alms to the poor, the needy, and the weak. They accused him before Herod who called him and asked him: \"Are you the one that instigating the people not to give the taxes to Caesar but to give it to the poor and the churches?\" Then he smote him with the sword, cutting off his head, and St. James received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "Clement of Alexandria, from the fathers of the second century, said: \"The soldier that seized the Saint, when he saw his courage, he realized that there must be a better life and asked the Saint for his forgiveness. Then the soldier confessed Christianity and received the crown of martyrdom (Acts 12:1,2) along with the Apostle in the year 44 A.D.\"", ar: "" } },
      { kind: 'reading', text: { en: "Because Herod saw that it pleased the Jews, he proceeded further to seize Peter also. So when he had apprehended him, he put him in prison, and delivered him to four squads of soldiers to keep him, intending to bring him before the people after Passover. (Acts 12:3-4)", ar: "" } },
      { kind: 'reading', text: { en: "So on a set day Herod, arrayed in royal apparel, sat on his throne and gave an oration to them. And the people kept shouting, \"The voice of a god and not of a man!\" Then immediately an angel of the Lord struck him because he did not give glory to God. And he was eaten by worms and died. (Acts 12:21-23)", ar: "" } },
      { kind: 'reading', text: { en: "As of the body of St. James, the believers took it, shrouded it, and buried it by the Temple. It was said that the body of St. James was translated to Spain, where James the elder considered to be its Apostle.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-3",
    title: { en: "Baramouda 3", ar: "3 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of the holy father Anba Michael, the Seventy First Pope of the See of St. Mark.", ar: "نياحة البابا ميخائيل الاسكندرى ال71" } },
      { kind: 'reading', text: { en: "On this day also of the year 862 A.M. (March 29th. 1146 A.D.) the holy father Pope Michael, the seventy first Patriarch of the See of , departed. He longed to the pure life since his young age so he became a monk in the monastery of St. Macarius. He lived in the desert until he was an old man, in a good pleasing life to God.", ar: "في مثل هذا اليوم من سنة 862 ش ( 29 مارس 1146 م ) تنيح الأب القديس البابا ميخائيل الحادي والسبعون من بطاركة الكرازة المرقسية وقد اشتاق إلى السيرة الطاهرة فترهب بدير القديس مقاريوس . ولبث في البرية إلى سن الشيخوخة في سيرة صالحة مرضية . فلما تنيح البابا غبريال السبعون . قضي الأساقفة والكهنة والأراخنة ثلاثة شهور في البحث عمن يصلح خلفا له وتقدم لترشيح نفسه راهب من دير القديس مقاريوس يدعي يوأنس بن كدران يعاونه في ذلك الأنبا يعقوب أسقف طنطا . إلا أن أساقفة الصعيد وكهنة الإسكندرية وأراخنة مصر لم يقبلوا ذلك ، أخيرا اتفق الجميع علي اختيار ثلاثة من الرهبان وهم . يوأنس أبو الفتح . وميخائيل من دير القديس مقاريوس . وسليمان الدخياري من دير البرموس . وألقوا قرعة بينهم فأصابت الراهب ميخائيل فرسموه بطريركا في 5 مسري سنة 861 ش ( 29 يوليه سنة 1145 م ) وكان شيخا جليلا محبا للفقراء والمساكين . واتخذ له كاتبا يحرر له ما يرسله إلى الأساقفة والكهنة من العظات والتعاليم . ولما مرض توجه إلى دير القديس مقاريوس وهناك تنيح بسلام بعد أن أقام علي الكرسي ثمانية شهور . صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "When Pope Gabriel (70) departed, the bishops, the priests and the lay leaders spent three month searching for who was best suited to succeed him. A monk from the monastery of St. Macarius, called Yoannis Ebn Kedran, came forward nominating himself supported in that by Anba Yacoub, bishop of Lekanah, Anba Christodolus, bishop of Fowa, and Anba Michael, bishop of Tanta.", ar: "" } },
      { kind: 'reading', text: { en: "Nevertheless, the bishops of Upper Egypt, the priests of Alexandria and the lay leaders of Cairo did not accept that choice. Finally they all agreed to choose three of the monks and those were: Yoannis Abu El-Fatah, Michael of St. Macarius monastery, and Soliman El-Dekhiary of El-Baramous monastery. They cast a lot among them, and the lot fell on the monk Michael, and they ordained him a Patriarch on the 5th of Mesra, 861 A.M. (July 29th, year 1145 A.D.). He was an honorable old man loving for the poor and the needy. He took for himself a scribe to write his sermons and teachings that he sent to the bishops and priests. When he fell sick, he went to the monastery of St. Macarius, where he departed in peace, after he stayed on the Chair for eight month.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. John, Bishop of Jerusalem.", ar: "نياحة يوحنا أسقف أورشليم" } },
      { kind: 'reading', text: { en: "On this day Anba John, Bishop of Jerusalem, departed. He was born to Jewish parents, who kept the Law of the Torah. They instructed and taught him well and he excelled in the Law of . He argued and disputed with the Christians until he became convinced of the coming of the Lord Christ, and that He was the true God. He believed on the hand of St. Justus, Bishop of Jerusalem, who baptized and ordained him a deacon. Because of his knowledge, and virtues they chose him a bishop of Jerusalem after the departure of St. Justus.", ar: "في مثل هذا اليوم تنيح الأنبا يوحنا أسقف أورشليم . وقد ولد من أبوين يهوديين حافظين لشريعة التوراة . فهذباه وعلماه كثيرا حتى نبغ في علم الشريعة وكان يجادل المسيحيين ويناظرهم فثبت له مجيء السيد المسيح وأنه اله حقيقي . فآمن علي يد القديس يسطس أسقف أورشليم ورسم شماسا . ونظرا لكثرة علمه وفضيلته انتخبوه أسقفا علي أورشليم . فلما ملك أريانوس أمر ببناء ما هدم من المدينة ثم بني برجا علي بابه لوحا من رخام مكتوبا عليه اسمه . ومنع المسيحيين من الصلاة في الجلجثة ومن العبور في ذلك المكان ولهذا اشتد ساعد اليهود والأمم فضايقوا المسيحيين كثيرا فأصاب هذا الأب من جزاء ذلك من البلايا والأحزان فطلب إلى الله أن يضمه إليه فقبلت طلبته وتنيح بسلام بعد أن أقام علي كرسي الأسقفية سنتين . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When Andrianus reigned, he commanded to rebuild the ruined parts of the city, he built a tower on the western gate (The gate of the Jewish temple) and he hanged an engraved tablet with his name on the door of that gate. He prevented the Christians from praying at the Golgotha and even passing through it. The Jews and the Gentiles became powerful and troubled the Christians much. Because of that many tribulations and sorrows befell this father, so he asked God that He might receive him. His supplication was accepted and he departed in peace after he stayed on the Episcopal Chair for two years.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-4",
    title: { en: "Baramouda 4", ar: "4 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد بقطر وداكيوس وأكاكيوس وإيرينى العذراء ومن معهم من \r\nالقرن الرابع الميلادى" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديسون . بقطر وداكيوس وايريني العذراء ومن معهم من رجال ونساء وعذارى . وذلك أنهم كانوا في زمان تملك الملك قسطنطين الكبير وابنه ، اللذين هدما معابد كثيرة للوثنيين ثم حولاها إلى كنائس علي اسم السيدة العذراء وأسماء القديسين . ولما ملك يوليانوس الكافر عضد عبادة الأوثان وأحسن كهنتها وقتل عددا عظيما من المسيحيين ورفع إليه بعضهم خبر هؤلاء القديسين وما أجروه بالبرابي والأصنام فقبض عليهم وعذبهم بأنواع العذاب وأخيرا قطع رؤوسهم فنالوا إكليل الشهادة صلاتهم تكون معنا . ولربنا المجد دائما آمين" } },
      { kind: 'heading', text: { en: "The Departure of Anba Isaac, the Disciple of Anba Apollo.", ar: "" } },
      { kind: 'reading', text: { en: "On this day the holy father Anba Isaac the Disciple of the great father Anba Apollo, departed. This holy man renounced the world since his young age. He became a monk in the wilderness of Sheahat (Scetis), and a disciple of for twenty five years. He fought a strenuous fight that weakened his body to kill his body desires, and control his will. He mastered the virtue of silence and quietness especially during the prayers and the Liturgies. He used to stand during the liturgy with his hands clasped and his head bent until the end of the prayer then he returned to his cell, shutting his door, and did not associate with any one that day. When they asked him: \"Why do you not talk to anyone who wish to talk to you during prayers or the Liturgy?\" He answered saying: \"There is time for talking and there is time for praying.\" When his departure drew near the fathers the monks gathered around him to receive his blessing and they asked him: \"Why did you flee from men.\" He answered them: \"I was not fleeing from men but from Satan. If a man hold a lighted lamp in the wind, it will be extinguished. So, it is with us when our hearts and minds shine because of the prayers and the Liturgy then we talk with each other, our hearts and minds become dark.\" And this holy father having finished his good spiritual strife, departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Gabriel II, the Seventy Pope of Alexandria, who was known as Ibn Turaik.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also of the year 861 A.M. (April 5th., 1145 A.D.) the great and holy father Pope Gabriel II, the seventy Pope of the See of , who was known as Ibn Turaik, departed. This Pope was from the nobles of Cairo, and he was a writer, scribe, distinguished scholar, with a commendable conduct. He transcribed with his hand many Arabic and Coptic books, he retained its contents and comprehended its interpretations. The elders of the people and the clergy chose him for the Patriarchal Chair, and his enthronement was on the , 847 A.M. (February 3rd., 1131 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "When he prayed his first Divine Liturgy in St. Macarius monastery as the custom of the previous Patriarchs, at the end of the Liturgy, he added to the profession after the saying: \"I believe and confess to the last breath, that this is the life-giving Flesh that Thine Only-Begotten Son, our Lord, God and Savior, Jesus Christ, took from our Lady, the Lady of us all, the holy Mother of God, Saint Mary,\" this sentence \"He made it one with His Divinity.\" The monks objected, lest it would be understood from that there was mingling between His Divinity and His Humanity, and asked him to refrain from using it. He refused saying: \"This statement was added by a decree from the council of bishops.\" After a great and lengthy discussion, they decided to add this sentence: \"Without mingling, without confusion, and without alteration,\" because of the fear of falling in the heresy of Eutyches, and he agreed with them.", ar: "" } },
      { kind: 'reading', text: { en: "During his papacy, he ordained 53 bishops and many priests, he drew up Canons and laws concerning inheritance, and many other matters. He never took any money from anyone, nor he touched the revenue of the churches, or that of the religious endowments for the poor. When the governor of that time asked him for money, the nobles and people collected three hundred Dinars in gold and gave them to the governor on his behalf. He remained on the Episcopal Chair for fourteen years, two month and two days, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-5",
    title: { en: "Baramouda 5", ar: "5 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Great Prophet Ezekiel, the son of Buzi.", ar: "نياحة حزقيال بن بوزي النبى" } },
      { kind: 'reading', text: { en: "On this day the great prophet Ezekiel the son of Buzi departed. This righteous man was a priest, and Nebuchadnezzar exiled him with king Jehoiachin to Babylon. There in the land of the Chaldeans by the river Chebar, the spirit of the Lord was upon him, and he prophesied about wondrous things for twenty two years. He spoke concerning the birth of the Lord Christ by the Lady the and how after she had , she would remain a virgin: \"Then He brought me back to the outer gate of the sanctuary which faces toward the east, but it was shut. And the LORD said to me, \"This gate shall be shut; it shall not be opened, and no man shall enter by it, because the LORD God of Israel has entered by it; therefore it shall be shut\" (Ezekiel 44:1-2). He prophesied concerning the baptism that sanctify the soul of the man and his body, soften his stony heart, and make him a son of God by the descent of the Holy Spirit upon him. He admonished the priests for their forsaken the teaching of the people, warning them that God will ask for their souls from them if they neglect teaching them. He prophesied concerning the common resurrection and the rising of the bodies with their souls, and about their rewards for whatever they deserve. He said many useful sayings which are of benefit to those who read them, and God manifested through him many signs and great wonders. When the children of Israel worshipped idols in Babylon, he rebuked them and their leaders rose up and killed him. They buried him in the tomb of Shem and Arphaxad.", ar: "في مثل هذا اليوم تنيح النبي العظيم حزقيال بن بوزي الكاهن . وكان هذا الصديق كاهنا ثم سباه نبوخذ نصر إلى بابل مع يهوياكين الملك . وهناك عند نهر خابور في أرض الكلدانيين حل عليه روح الرب فتنبأ بأمور عجيبة مدة اثنتين وعشرين سنة منها قوله عن ميلاد السيدة العذراء والدة الإله وبقائها بعد الولادة عذراء : ان الرب أراه متجها للمشرق وهو مغلق . وقال له : &quot; هذا الباب يكون مغلقا لا يفتح ولا يدخل منه إنسان لأن الرب اله إسرائيل دخل منه فيكون مغلقا (حز 44 : 1 و 2) .وتنبأ عن المعمودية التي تقدس نفس الإنسان وجسمه وتلين قلبه الحجري وتجعله ابنا لله بحلول الروح المقدس عليه وبكت الكهنة علي تركهم تعليم الشعب وحذرهم من ذلك مبينا لهم أن الله يطلب نفوسهم منهم ان هم أهملوا تعليمهم . ثم تنبأ عن القيامة العامة وعن قيامة الأجساد بأرواحها التي كانت متحدة بها وعن مجازاتها بما تستحقه وذكر أقوالا كثيرة نافعة لكل من يقف عليها وأظهر الله علي يديه آيات عظيمة . ولما عبد بنو إسرائيل الأصنام في بابل بكتهم فوثب عليه رؤساؤهم وقتلوه ثم دفنوه في مدافن سام وار فكشاد صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة يعقوب بن زبدى" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة يعقوب بن زبدي. صلاته تكون معنا و لربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Hepatius, Bishop of Gangra.", ar: "استشهاد القديس هيباتيوس أسقف غنغرة" } },
      { kind: 'reading', text: { en: "On this day also St. Hepatius, Bishop of Gangra, in the province of Paphlognia (Pavlagonia), was martyred. He was in the early part of the fourth century, and he attended the first Universal Council at Nicea, year 325 A.D. He was one of the great fathers that defended the Divinity of the Word of God and His equality with His Father in essence, and refuted the error of the heresies of Arius, Appolonius, Novatius and others.", ar: "في مثل هذا اليوم استشهد القديس هيباتيوس أسقف غنغرة في إقليم بافلاغونيا ، ورأس هذه الأبرشية وساس شعبها في أوائل القرن الرابع ، فحضر المجمع المسكوني النيقاوي الأول سنة 325 م . وكان من آبائه العظام المحامين عن ألوهية كلمة الله ومساواته لأبيه في الجوهر ، مفندا ضلال الهرطقة الأريوسيين والأبوليناريين وانوفاتيانيين وغيرهم ." } },
      { kind: 'reading', text: { en: "God had honored him with the gift of performing wonders, and was called the wonder worker. One of his wonders, during the days of Emperor Constans the son of Constantine the great: A beast entered the royal barns. The Emperor sent to the Saint asking him to go to the barns and kill that beast. The holy shepherd went there and after he prayed, he asked the servants to collect firewood in the yard of the city and put it on fire and they did. The Saint took his staff and put it in the beast's mouth and led it to the fire and it was burnt. As a commemoration of this miracle the Emperor ordered to hang the saint's picture over the doors of the barns.", ar: "وقد شرفه الله بموهبة صنع العجائب التي فعلها في أوقات كثيرة وبأنواع عديدة ولهذا لقب بالعجائبي . ومن عجائبه أنه في أيام الملك قسطندي بن قسطنطين العظيم ،دخل من البر إلى المخازن الملكية تنين مخيف . فأرسل إلى القديس طالبا منه أن يمضي إلى المخازن ويقتل هذا التنين . فذهب الراعي القديس إلى هناك وبعد أن صلي قال للخدام أن يجمعوا حطبا في ساحة المدينة ويضرموا به النار ففعلوا فأخذ القديس عكازه ووضعه في فم التنين وقادة بها ملجما إلى الأتون فاحترق وتذكارا لهذه الأعجوبة أمر الملك بتعليق رسم القديس علي جدار المخازن وفيما كان القديس راجعا من نيقية بعد انعقاد المجمع المسكوني الأول قاصدا غنغرة خرج عليه فريق من الهراطقة كانوا قد كمنوا له في الطريق ، فوثبوا عليه ورجموه بالحجارة ومات شهيدا ( في يوم 31 آذار ) ثم طرحوا جسده في مخزن تبن فلما علم أهالي مدينة غنغرة بوفاة راعيهم الصالح أسرعوا إلى المحل الذي قتل به ونقلوا بقاياه المقدسة بكل إكرام ودفنوها في المدينة . بركاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "On his way back, from Nicea after attending the first Universal Council, to Gangra, a group of heretics were waiting for him by the road, attacked him, stoned him and he was martyred (On the 31st. day of March) then threw his body in a hay barn. When the people of the city of Gangra knew of the departure of their good shepherd, they went in hast to the place where he was martyred and took the holy remains with great honor and buried him in the city.", ar: "" } },
      { kind: 'reading', text: { en: "May his blessings be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-6",
    title: { en: "Baramouda 6", ar: "6 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Appearance of the Lord to Thomas the Apostle after His Resurrection.", ar: "ظهور الرب لتوما" } },
      { kind: 'reading', text: { en: "On this day is the commemoration of the appearance of the Lord Christ, to Whom is the glory, to Thomas the apostle on the eighth day from the glorious Resurrection as the Bible said: \"And after eight days His disciples were again inside, and Thomas was with them. Jesus came, the doors being shut, and stood in the midst, and said, \"Peace to you!\" Then He said to Thomas, \"Reach your finger here, and look at My hands; and reach your hand here, and put it into My side. Do not be unbelieving, but believing.\" And Thomas answered and said to Him, \"My Lord and my God!\" Jesus said to him, \"Thomas, because you have seen Me, you have believed. Blessed are those who have not seen and yet have believed.\" (John 20:26-29) When St. Thomas put his hand in the side of the Lord, his hand was about to be burned by the fire of the Divinity, and when he confessed His Divinity his hand was healed from the pain of the burning.", ar: "في هذا اليوم تذكار ظهور الرب يسوع له المجد لتوما الرسول , في اليوم الثامن من القيامة المجيدة وذلك كما يقول الكتاب &quot; وبعد ثمانية أيام كان تلاميذه أيضا داخلا وتوما معهم . فجاء يسوع والأبواب مغلقة ، ووقف في الوسط وقال : سلام لكم . ثم قال لتوما هات إصبعك إلى هنا وأبصر يدي وهات يدك وضعها في جنبي ولا تكن غير مؤمن بل مؤمنا . أجاب توما وقال له : ربي والهي . قال له يسوع لأنك رأيتني يا توما آمنت طوبى للذين آمنوا ولم يروا &quot; (يو 20 : 26 – 29 ) فالقديس توما عندما وضع يده في جنب الرب كادت تحترق يده من نار اللاهوت . وعندما اعترف بألوهيته برئت من ألم الاحتراق . صلاة هذا الرسول تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May the prayers of this Apostle be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Mary of Egypt.", ar: "نياحة مريم المصرية السائحة" } },
      { kind: 'reading', text: { en: "On this day also of the year 137 A.M. (421 A.D.) the hermit St. Mary of Egypt departed. She was born in the city of Alexandria about the year 61 A.M. (345 A.D.) from Christian parents.", ar: "في مثل هذا اليوم من سنة 137 ش (421م ) تنيحت القديسة السائحة مريم القبطية . وقد ولدت بمدينة الإسكندرية نحو سنة 61 ش (345م ) من أبوين مسيحيين . ولما بلغت اثنتي عشرة سنة خدعها عدو البشر . فجعلها له فخا وشركا فاصطاد بها نفوسا كثيرة لا تحصي ومكثت علي هذه الحال الآثمة سبعة عشر عاما حتى أدركتها محبة الله فرأت قوما ذاهبين إلى بيت المقدس فسافرت معهم وإذ لم يكن معها أجرة سفرها ، أسلمت ذاتها لأصحاب السفينة حتى وصلت إلى بيت المقدس وهناك أيضا كانت تأتي هذا الآثم ولما أرادت الدخول من باب كنيسة القيامة شعرت بقوة خفية جذبها من الخلف . وكانت كلما أرادت الدخول تشعر بمن يمنعها وللحال تحققت أن ذلك لسبب نجاستها . فرفعت عينيها وهي منكسرة القلب وبكت مستشفعة بالسيدة العذراء وسألتها بدموع حارة أن تتشفع فيها لدي ابنها الحبيب ثم تشجعت وأرادت الدخول مع الداخلين فلم تجد ممانعة فدخلت مع الساجدين وصلت إلى الله طالبة أن يرشدها إلى ما يرضيه ." } },
      { kind: 'reading', text: { en: "When she became twelve years old, Satan the enemy of the human race, seduced her, led her astray, and made her his net through which he caught innumerable souls.", ar: "ثم وقفت أمام أيقونة العذراء البتول الزكية وتوسلت إليها بحرارة أن ترشدها إلى حيث خلاص نفسها . فأتاها صوت من ناحية الأيقونة يقول : إذا عبرت الأردن تجدين راحة وطمأنينة &quot; فنهضت مسرعة وخرجت من ساحة القيامة . وفي الطريق قابلها إنسان . وأعطاها ثلاثة دراهم من الفضة ابتاعت بها ثلاثة أرغفة من الخبز ثم عبرت نهر الأردن إلى البرية ومكثت بها سبعا وأربعين سنة منها سبع عشرة سنة وهي تقاتل العدو ضد الآثم الذي تابت عنه حتى تغلبت بنعمة الله وكانت تقتات طول هذه المدة بالحشائش وفي السنة الخامسة والأربعين لساحتها خرج القديس زوسيما القس إلى البرية حسب عادة الرهبان هناك في مدة صوم الأربعين المقدسة للاختلاء والتنسك . وبينما هو يسير في البيداء رأي هذه القديسة عن بعد فظنها خيالا وصلي إلى الله أن يكشف له أمر هذا الخيال . فألهم أنه إنسان . فأراد اللحاق به فكان يهرب أمامه ولما رأت أنه لم يكف عن تعقبها نادته من وراء أكمة قائلة : يا زوسيما . ان شئت أن تخاطبني فارم شيئا أستتر به لأني عارية . فتعجب إذ دعته باسمه . ورمي لها ما استترت به فجاءت إليه وبعد السلام والمطانيات سألته أن يصلي عليها لأنه كان كاهنا واستوضحها عن سيرتها . فقصت عليه جميع ما جري لها من أول عمرها إلى ذلك الوقت . ثم التمست منه أن يحضر معه في العام القادم القربان المقدس ليناولها منه ." } },
      { kind: 'reading', text: { en: "She continued in this sinful conduct for seventeen years until the mercy of God touched her life, she met people going to Jerusalem and she went with them. Since she did not have what to pay for the trip, she gave her self to the owners of the ship in return, until she came to Jerusalem. She also went on doing the same there. She wished to enter through the door of the church of the Resurrection, but she felt a hidden power pulling her from the back preventing her from entering the church. Whenever she tried to enter she felt as someone preventing her from doing so, and right away she realized that was because of her uncleanliness. She lifted up her eyes with a broken heart, and she wept interceding with St. Mary and asked her to intercede on her behalf before her Beloved Son. She felt encouraged and wished to enter with those entering, nothing prevented her from entering, and she prayed therein to God asking Him to guide her for what was pleasing to Him.", ar: "وفي العام التالي حضر إليها وناولها من السرائر الإلهية ثم قدم لها ما معه من التمر والعدس فتناولت بعض حبات من العدس المبلول , وسألته أن يعود في العام المقبل وحضر إليها في الميعاد فوجدها قد تنيحت ورأي أسدا واقفا بجوارها . وعند رأسها مكتوب : &quot; ادفن مريم المسكينة في التراب الذي منه أخذت &quot; فتعجب من الكتابة ومن الأسد . وفيما هو مفكر كيف يحفر الأرض لمواراتها تقدم الأسد وحفر الأرض بمخالبه فصلي الأب عليها ودفنها . ثم عاد إلى ديره وأخبر الرهبان بسيرة هذه القديسة فازدادوا ثباتا في المراحم الإلهية وتقدما في السيرة الروحية وكانت سنو حياتها ستا وسبعين سنة . صلاتها تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "She stood before the icon of the blessed and pure Virgin, and asked her fervently to guide her that she might save her soul. A voice came out of the icon saying: \"If you cross the Jordan river you will find rest and salvation.\" She rose in haste and when she left the court yard of the resurrection and on her way she met a man who gave her three small coins with which she bought bread. Then she crossed the Jordan river to the wilderness where she lived for forty seven years. She strove strenuously for seventeen years, Satan fought against her by the fornication that she repented from. She overcame with the grace of God and she ate all this period the herbs of the desert.", ar: "" } },
      { kind: 'reading', text: { en: "In the forty fifth year of her living in the desert, St. Zosima went to the wilderness, according to the custom of the monks there, during the holy Forty Days of fast for devotion and asceticism. While he was walking in the desert he saw this Saint from far and he thought that she was a shadow or mirage. He prayed to God to reveal to him the fact about this mirage, and he was inspired that it was a human being. He went toward the shadow, but it fled from him. When she saw that he is insisting on following her, she called him from behind a hill saying: \"O Zosima if you wish to talk to me, throw me a rag that I may cover myself for I am naked.\" He marvelled for she called him by his name, he threw to her what she covered herself with, and she came to him. After the greetings and the metanias, she asked him to pray for her because he was a priest. He asked her to tell him the story of her life from the beginning to the present time. After she told him, she asked him to bring with him in the next year the Holy Eucharist to partake of it.", ar: "" } },
      { kind: 'reading', text: { en: "In the next year he came to her and she partook of the Holy Mysteries, then he gave her what he had from dates and lentils, she only took a handful of lentils, and she asked him to come to her in the next year. When he came to her in the next year he found that she had departed, a lion standing beside her and writing beside her saying \" Bury Mary, the poor woman, in the dust of which she was created.\" He marvelled from the writing and from the lion that was protecting her body and while he was thinking how he was going to dig to bury her, the lion came and dug a grave for her. He prayed over her and buried her. When he returned to his monastery, he told the monks the story of the strife of this holy woman, and they all increased in steadfastness in the Divine Mercy and progressed in the spiritual life. All the years of her life were seventy six years.", ar: "" } },
      { kind: 'reading', text: { en: "May her prayers be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-7",
    title: { en: "Baramouda 7", ar: "7 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of the Righteous Joachim, The Lord Christ Grandfather.", ar: "نياحة يواقيم البار والد العذراء أم الاله" } },
      { kind: 'reading', text: { en: "On this day the righteous Joachim (Yonakhir - Zadok) departed. He was the father of St. Mary, the Theotokos, the mother of God incarnate. He was of the seed of , and of the tribe of Judah, for he was the son of Jotham, the son of Lazarus, the son of Eldad who ascended up in genealogy to Solomon the king, the son of David whom God promised that his seed should reign over the children of Israel for ever. The wife of this righteous man, was barren, and both of them prayed and entreated God continually to give them a child. Having accepted their petition , which satisfied all the men of the world, and removed from them the bitterness of servitude, and He made Joachim worthy to be called the father of the Lord Christ in regard of His marvelous and wondrous Incarnation. After God had pleased him with the birth of our Lady, his heart was rejoiced and he offered his offerings, and the shame had been removed from him, he departed in peace when the .", ar: "في مثل اليوم تنيح الصديق يواقيم (سمي أيضا بوناخير وصادوق ) والد السيدة العذراء والدة الإله بالجسد . وهذا كان من نسل داود من سبط يهوذا وهو ابن يوثام بن لعازر بن اليود الذي يصعد في النسب إلى سليمان بن داود الذي وعده الله أن نسله يملك علي بني إسرائيل إلى الأبد . هذا الصديق كانت زوجته عاقرا وبمداومته معها علي السؤال والطلبة من الله رزقهما ثمرة صالحة حلوة أشبعت كل أهل العالم ونزعت من أفواههم مرارة العبودية ولهذا استحق أن يدعي أبا للسيد المسيح من حيث التجسد العجيب الغريب . وبعد أن أقر الله عينيه بمولد السيدة وفرح قلبه قدم قربانه وزال عنه العار . وتنيح بسلام حيث كانت العذراء ابنة ثلاث سنين . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Macrobius.", ar: "نياحة القديس مقرفيوس" } },
      { kind: 'reading', text: { en: "On this day also the saint Anba Macrobius, the son of the governor of the city of Kaw, departed in peace. When Anba Severus, Archbishop of Antioch, was wondering around the cities of Upper Egypt, he came to the city of Kaw and Macrobius ministered unto him. He accompanied Anba Severus in his visit to the monastery of Anba Moses, where he saw from the holiness of the monks, their asceticism and devoutness, made him ask Anba Moses to accept him as a monk. Anba Moses indicated to him the hardship of the monastic life and its difficulties especially he was raised in luxury and family wealth, and the one that slept on silk, could not take the rough life.", ar: "في القرن السادس المسيحي أيام الإمبراطور جستنيان" } },
      { kind: 'reading', text: { en: "When Anba Moses saw the insistence of Macrobius on the monastic life he asked him first to resign his job that he took after his father, and to relinquish all his money and possessions. He went to his city Kaw, appointed his brother in his place, returned and put on the monastic garb. When his brothers Paul, Ilias, and Joseph saw what their brother had done, they came to him and became monks by the hands of Anba Moses.", ar: "" } },
      { kind: 'reading', text: { en: "Anba Macrobius built many monasteries and many monks, about a thousand gathered around him, and he also built convents for about a thousand nuns. He used his money to build many places for those that did not desire the monastic life, and he supported those who sought his help. Then he sent to Anba Moses asking to send him brethren to prepare those gathered around him for the monastic life, they came and put on them the monastic garb.", ar: "" } },
      { kind: 'reading', text: { en: "Christians from the cities of Assuit, Shatb, and neighboring cities came and gave him many gifts and much money to help him in building the churches and monasteries. He accepted it from them and blessed them. Anba Macrobius increased in virtues, asceticism and giving alms to the weak, needy, widows, orphans and the lonely, beside caring for his monasteries. His alms were from his own money not from that was offered. God granted St. Macrobius the gift of healing, they brought him the sick and he healed them with the power of God and the strength of their faith.", ar: "" } },
      { kind: 'reading', text: { en: "The father the Patriarch Anba Theodosius, heard about him and he wrote to him praising and encouraging him to be steadfast in virtue, asceticism and loving the strangers and asked him to come for the people of Alexandria to be blessed by him. When he came to the Patriarch, he rejoiced with him and called the people of Alexandria to receive the blessing from him, and he ordained him a priest. Macrobius returned to his monastery, the people of Assuit and Shatb received him with songs and hymns until they came to the monastery. Many miracles were performed through his hands, and when he finished his good strife, he departed in peace. Multitudes gathered from Assuit, Shatb, Abu-Sergah, Kaw and the neighboring cities, and his brother Anba Yousab, who was appointed as his successor in running the monasteries in the fear of God, prayed and buried him.", ar: "" } },
      { kind: 'reading', text: { en: "The appearance of his body was on the , seven hundred thirty three years after his departure by the hands of the deacon Los El-Talawy the servant of his monastery's church, during the days of Anba Yousab, bishop of Akhmeem and the notable Isaac the scribe of the prince Eiz-Eldeen El-Hamawy. Anba Yousab, bishop of Akhmeem, took the body out of its tomb in the mountain, down to the church of the monastery, where they buried him with hymns and praises.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Sts. Agapius, Theodora, and Metruf.", ar: "نياحة أغابيس وتاودورة والقديس أبي مقروفة" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the departure of Sts. Agapius and Theodora the martyrs, and the commemoration of St. Metruf the spiritual son of Anba Moses the Abbot of El-Baliana monastery.", ar: "في مثل هذا اليوم تذكار نياحة أغابيس وتاودوره الشهيدتان وتذكار القديس أبى مقروفة الابن الروحي لأنبا موسى صاحب دير البلينا . شفاعتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May their intercession be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-8",
    title: { en: "Baramouda 8", ar: "8 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of the Holy Virgins: Agape, Eirene, and Shiona.", ar: "استشهاد اغابى وإيرينى وصوفيا" } },
      { kind: 'reading', text: { en: "On this day the three holy virgins: Agape, Eirene, and Shiona (Susinia) were martyred. They were from Thessalonica, and worshipped Christ as their parents. They chose the life of chastity and they agreed to devote themselves to the ascetic life. They fasted and prayed unceasingly, visited the convents often and participated with the virgins in their prayers and asceticism. When Maximianus the infidel, reigned, he restored the worship of the idols and shed the blood of many Christians. These saints were afraid and they fled to the mountain and hid themselves in a cave devoting themselves to their worship and asceticism.", ar: "في مثل هذا اليوم استشهدت العذارى القديسات أغابى وايريني وصوفية . وهؤلاء كن من أهل تسالونيقية ، وكن عابدات للمسيح عن آبائهن ثم اخترن عيشة البتولية واتفقن علي السلوك في الفضيلة وكن مداومات علي الاصوام المتواصلة والصلوات الكثيرة مترددات علي أديرة العذارى متنسكات مع الراهبات . فلما تملك مكسيميانوس الكافر (نحو أواخر القرن الثالث ) وأثار عبادة الأصنام وسفك دماء كثيرين من المسيحيين خافت القديسات وهربن إلى الجبل واختبأن في مغارة مداومات علي نسكهن وعبادتهن وكانت هناك امرأة عجوز مسيحية تفتقدهن بكل ما يحتجنه كل أسبوع وتبيع ما يعملنه بأيديهن وتتصدق عنهن بما يفضل . وحدث أن رأي أحد الأشرار كثرة خروج هذه العجوز إلى الجبل . فتبعها عن بعد إلى أن عرف المغارة التي تدخل إليها فاختبأ حتى لا تراه عند عودتها ، وكان يظن أنها تخبئ أشياء ثمينة فلما خرجت من المغارة وابتعدت عنها دخل إليها فوجد الجواهر النفيسة عرائس المسيح وهن قائمات يصلين فربطهن وجذبهن وأحضرهن إلى والي تسالونيقية . فسألهن عن أيمانهن فأقررن أنهن مسيحيات عابدات للمصلوب فحنق الوالي عليهن وعذبهن كثيرا ثم طرحهن في النار فأسلمن أرواحهن ونلن إكليل الشهادة . صلاتهن تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "Every week, an aged Christian woman visited them bringing all things needed and took the work of their hands to sell it, and distributed the remainder as alms to the poor. One day a malicious person observed the frequent visits of this old woman to the mountain, he followed her secretly until he knew the cave that she entered. He hid himself so she did not see him on her way back, and he thought that she was hiding precious things in it. After she left the cave by a distance he entered the cave and he found the precious pearls the prides of the Christ standing praying. He bound them, dragged them away, and brought them to the Governor of Thessalonica. He asked them about their faith, they confessed that they were Christians worshipping that Who was Crucified. The Governor became wrath with them, tortured them much, then cast them into the fire, and they delivered up their souls and received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the One Hundred and Fifty believers by the hand of king of Persia.", ar: "استشهاد 150 شهيد على يد ملك الفرس" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the incident of the martyrdom of one hundred and fifty believers by the king of Persia. This king besieged Christian cities which were near the borders of his country, and captured many of them. When they refused to worship the sun and the stars, he commanded to cut off their heads, and they received the crowns of martyrdom.", ar: "في مثل هذا اليوم تذكار حادثة استشهاد مائة وخمسين من المؤمنين قتلوا في ساعة واحدة بيد ملك الفرس وذلك أن هذا الملك كان قد أغار علي بلاد المسيحيين المتاخمة لحدود بلاده وسبي منهم كثيرين . ولما لم يطيعوه ليعبدوا الشمس والكواكب أمر بقطع رؤوسهم . فنالوا أكاليل الشهادة . صلاتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May their prayers be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-9",
    title: { en: "Baramouda 9", ar: "9 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The commemoration of the Wonder that took place on the hand of Pope Sinuthius (Shenouda I) the Fifty Fifth Patriarch.", ar: "ظهور أية على يد البابا سانوتيوس الخامس والخمسين الاسكندرى" } },
      { kind: 'reading', text: { en: "On this day also a great sign was made manifest through our holy father of Alexandria. This Pope went to the desert of Scetis in order to fast the Holy Lent with the fathers the monks. On Palm Sunday many Arabs came to the desert of Scetis to plunder the monasteries. They stood on the rock east of the church of St. Macarius. Their swords were drawn in their hands ready to kill and steal. The bishops and the monks gathered together and decided to leave the desert before the Holy Feast of Resurrection (Easter) and they took counsel with Pope Shenouda who told them; \"As for me I will not leave the desert until I complete the Pascal week. On Maundy Thursday the situation became worse. The Pope took his staff that had the sign of the cross on it and he wanted to go out to meet the Arabs saying: \"It is better for me to die with the people of God\" but they prevented him from going out, but instead, he strengthened and comforted them. Then he went forth to meet the Arabs with his staff in his hand. When they saw him, they retreated and fled away as if they were pursued by an army of soldiers and from this day onwards they never came back to do any harm.", ar: "في مثل هذا اليوم ظهرت آية عظيمة علي يد أبينا القديس البابا سانوتيوس الخامس والخمسين من باباوات الإسكندرية ، الذي تولي الكرسي من 13 طوبة سنة 575 ش إلى 24 برمودة سنة 596 ش (سنة 880). وهي أن هذا البابا كان قد صعد إلى برية شيهيت ليصوم الأربعين المقدسة مع الآباء الرهبان . وفي أسبوع الشعانين أقبل كثيرون من العربان علي البرية لنهب الأديرة وأقاموا هناك علي الصخرة الكائنة شرقي الكنيسة وسيوفهم مجردة استعدادا للقتل والسلب . فاجتمع الأساقفة والرهبان وقرروا مبارحة البرية قبل عيد القيامة المجيد ، ورفعوا الآمر إلى البابا سانوتيوس ، فقال له : أما أنا فإني لا أفارق البرية إلى أن أكمل الفصح وفي يوم الخميس الكبير عظم الآمر وزاد القلق فأخذ هذا البابا عكازه الذي عليه علامة الصليب , وأراد الخروج لمقابلة العربان وهو يقول &quot; الأفضل لي أن أموت مع شعب الله &quot; فمنعوه من الخروج ولكنه عزاهم وقواهم ثم خرج إلى العربان وبيده ذلك العكاز . فعندما رأوه رجعوا إلى الوراء وفروا هاربين كأن جندا كثيرين قد صدوهم عن ذلك المكان ولم يعودوا إليه من ذلك اليوم بقصد سيئ , صلاته هذا الأب تكون معنا (ذكر تاريخه تحت اليوم الرابع والعشرين من شهر برمودة ) ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "The prayers of this father be with us and glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Zosimus (Zocima).", ar: "نياحة القس زوسيما الراهب" } },
      { kind: 'reading', text: { en: "On this day in the middle of the fifth century the ascetic father and the struggling monk Abba Zocima the priest, departed. This Saint was born about the middle of the fourth century from Christian and holy parents, who were from Palestine. When he was five years old they handed him to a righteous old monk, who raised him in a Christian manner and taught him the doctrine of the church, and shortly after they ordained him a deacon. He became a righteous monk and grew in virtues.", ar: "في مثل هذا اليوم من منتصف الجيل الخامس للميلاد تنيح الأب العابد والراهب المجاهد القس زوسيما . ولد هذا القديس في أواسط الجيل الرابع للميلاد من أبوين مسيحيين قديسين من أهل فلسطين . وفي السنة الخامسة من عمره سلماه لراهب شيخ قديس . فرباه تربية مسيحية وعلمه العلوم الدينية وبعد قليل رسموه شماسا . وصار راهبا تقيا فنما في الفضيلة نموا زائدا ." } },
      { kind: 'reading', text: { en: "He was continually praising God and he read the Scriptures day and night and during work also. When he had completed thirty five years in the monastery they ordained him a priest. Then he increased his ascetic labors and struggle. After spending thirteen years in this struggle the enemy sowed in his mind the evil thought that he was superior to all his contemporaries in virtues and righteousness. But the Lord willed to turn him away from this thought. He sent an angel to him and commanded him to go to the monastery which was near the river Jordan. He rose up and went to the monastery and he found therein righteous old men who were more perfect in their contending than him. He realized that he was far from what he thought in himself and he stayed there with them.", ar: "وكان ملازما للتسبيح والقراءة نهارا وليلا ، وفي وقت العمل أيضا ولما أكمل خمسا وثلاثين سنة في الدير رسموه قسا فتزايد في نسكه وزهده وجهاده وبعد أن قضي كذلك ثلاث عشرة سنة زرع العدو في فكره أنه قد أصبح يفوق كل أهل زمانه في التقوى والفضيلة ولكن الرب شاء أن يرده عن هذا الظن فأرسل إليه ملاكا أمره بالانتقال إلى الدير القريب من الأردن فقام ومضي إليه فوجد فيه شيوخا قديسين أكمل منه في سيرتهم. فتبين له عندئذ أنه كان بعيدا عما ظنه في نفسه فأقام عندهم . وكان من عادة هؤلاء الشيوخ أنهم في أيام الصوم الكبير بعدما يصومون الأسبوع الأول منه ، يتقربون من الأسرار المقدسة ثم يخرجون من الدير وهم يتلون المزمور السادس والعشرين (المزمور السابع والعشرون حسب طبعة بيروت) وعند نهايته يصلون وبعد أن يبارك عليهم الرئيس يودعون بعضهم بعضا ويتفرقون في براري الأردن يجاهد كل منهم علي حده فصار القديس زوسيما يخرج معهم كل عام ويجول في البرية سائلا الله أن يريه من هو أكمل منه فوجد في بعض جولاته القديسة مريم القبطية . واستعلم منها عن سيرتها وسبب تجولها . وطلبت منه التقرب من الأسرار الإلهية فأتاها بها في العام المقبل وقربها ثم أفتقدها في العام التالي ، فوجدها قد تنيحت فواراها التراب وقص سيرتها علي رهبان الدير وبعد أن عاش تسعا وتسعين سنة تنيح بسلام . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "The custom of those monks during the Holy Lent, was that after they had fasted the first weak they partook the Holy Communion, then they left the monastery singing the twenty six psalm, and at the end of it, they prayed together. Then the abbot blessed them and they bed farewell to each other. Then they dispersed in the desert of Jordan and each of them carried out his spiritual fight by himself. St. Zosimus used to go out with them each year wondering in the desert asking God to show him who was more perfect than him.", ar: "" } },
      { kind: 'reading', text: { en: "As he was wondering about he met Mary the Egyptian (Coptic). He learned from her about her life history and the reason for her wondering in the desert. She asked him to visit her after one year to give her the Holy Mysteries. He came to her in the next year and gave her the Holy Communion. In the year after he revisited her again but he found her had departed and he buried her and told the monks of the monastery concerning her strife. After he had lived ninety nine years he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-10",
    title: { en: "Baramouda 10", ar: "10 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of Anba Isaac, the Disciple of Anba Apollo.", ar: "نياحة الانبا إيساك تلميذ أبللو" } },
      { kind: 'reading', text: { en: "On this day the holy father Anba Isaac the Disciple of the great father Anba Apollo, departed. This holy man renounced the world since his young age. He became a monk in the wilderness of Sheahat (Scetis), and a disciple of for twenty five years. He fought a strenuous fight that weakened his body to kill his body desires, and control his will. He mastered the virtue of silence and quietness especially during the prayers and the Liturgies. He used to stand during the liturgy with his hands clasped and his head bent until the end of the prayer then he returned to his cell, shutting his door, and did not associate with any one that day. When they asked him: \"Why do you not talk to anyone who wish to talk to you during prayers or the Liturgy?\" He answered saying: \"There is time for talking and there is time for praying.\" When his departure drew near the fathers the monks gathered around him to receive his blessing and they asked him: \"Why did you flee from men.\" He answered them: \"I was not fleeing from men but from Satan. If a man hold a lighted lamp in the wind, it will be extinguished. So, it is with us when our hearts and minds shine because of the prayers and the Liturgy then we talk with each other, our hearts and minds become dark.\" And this holy father having finished his good spiritual strife, departed in peace.", ar: "في مثل هذا اليوم تنيح الأب القديس المجاهد الأنبا ايساك تلميذ الأب الكبير الأنبا أبلوس . زهد هذا القديس العالم منذ صغره . وترهب في برية شيهيت ، وتتلمذ للأنبا أبلوس مدة خمس وعشرين سنة ، أجهد نفسه فيها جهادا أذاب جسمه بقتل الأهواء النفسية ، حتى ملك استقامة العزم ، وأتقن فضيلة الصمت والهدوء أثناء الصلوات والقداسات . وكان من عادته في وقت القداس أنه يظل واقفا مكتوف اليدين حاني الرأس حتى نهاية الصلاة ، ثم يعود إلى قلايته ويغلق بابها عليه ولا يقابل أحدا في ذلك اليوم . ولما سألوه : &quot; لم لا تكلم من يريد كلامك وقت الصلاة أو القداس ؟ &quot; أجابهم قائلا : &quot; للكلام وقت ، وللصلاة وقت &quot; ولما دنا وقت وفاته اجتمع عنده الآباء الرهبان لينالوا بركته وسألوه : &quot; لماذا كنت تهرب من الناس &quot; ؟ فأجابهم &quot; ما كنت أهرب من الناس بل من الشيطان . لأن الإنسان إذا مسك مصباحا متقدا في الهواء ينطفئ . وهكذا نحن إذا ضاء عقلنا من الصلاة والقداس ثم تشاغلنا بالأحاديث فان عقلنا يظلم &quot; . ولما أكمل هذا الأب جهاده الصالح تنيح بسلام . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Gabriel II, the Seventy Pope of Alexandria, who was known as Ibn Turaik.", ar: "نياحة البابا غبريال بن بطريك الثانى" } },
      { kind: 'reading', text: { en: "On this day also of the year 861 A.M. (April 5th., 1145 A.D.) the great and holy father Pope Gabriel II, the seventy Pope of the See of , who was known as Ibn Turaik, departed. This Pope was from the nobles of Cairo, and he was a writer, scribe, distinguished scholar, with a commendable conduct. He transcribed with his hand many Arabic and Coptic books, he retained its contents and comprehended its interpretations. The elders of the people and the clergy chose him for the Patriarchal Chair, and his enthronement was on the , 847 A.M. (February 3rd., 1131 A.D.).", ar: "في مثل هذا اليوم من سنة 861 ش ( 5 أبريل سنة 1145 م ) تنيح الأب القديس العظيم البابا غبريال الثاني البطريرك السبعون من باباوات الكرازة المرقسية الشهير بابن تريك . هذا البابا كان من كبار مدينة مصر وأراخنتها ، وكان كاتبا ناسخا عالما فاضلا ذا سيرة حميدة . وقد نسخ بيده كتبا كثيرة قبطية وعربية فوعي محتوياتها وفهم معانيها فاختاره مقدمو الشعب ورؤساؤهم لكرسي البطريركية ، وتمت رسامته يوم 9 أمشير سنة 847 ش ( 3 فبراير سنة 1131 م )" } },
      { kind: 'reading', text: { en: "When he prayed his first Divine Liturgy in St. Macarius monastery as the custom of the previous Patriarchs, at the end of the Liturgy, he added to the profession after the saying: \"I believe and confess to the last breath, that this is the life-giving Flesh that Thine Only-Begotten Son, our Lord, God and Savior, Jesus Christ, took from our Lady, the Lady of us all, the holy Mother of God, Saint Mary,\" this sentence \"He made it one with His Divinity.\" The monks objected, lest it would be understood from that there was mingling between His Divinity and His Humanity, and asked him to refrain from using it. He refused saying: \"This statement was added by a decree from the council of bishops.\" After a great and lengthy discussion, they decided to add this sentence: \"Without mingling, without confusion, and without alteration,\" because of the fear of falling in the heresy of Eutyches, and he agreed with them.", ar: "وحدث أنه عندما صلي أول قداس في دير القديس مقاريوس كعادة البطاركة قديما أن أضاف علي الاعتراف الذي يتلى في آخر القداس بعد قوله &quot; أؤمن وأعترف إلى النفس الأخير أن هذا جسد ابنك الوحيد الجنس ربنا وإلهنا ومخلصنا يسوع المسيح الذي أخذه من سيدتنا كلنا والدة الإله القديسة مريم &quot; هذه العبارة &quot; وصيره واحدا مع لاهوته &quot; فأنكرها عليه الرهبان خشية أن يفهم من ذلك أنه حصل امتزاج . وطلبوا منه تركها فامتنع قائلا : &quot; أنها أضيفت بقرار من مجمع الاساقفه &quot; وبعد مباحثات طويلة تقرر إضافة هذه الجملة &quot; بدون امتزاج ولا اختلاط ولا تغيير وذلك خوفا من الوقع في هرطقة أوطيخي فوافقهم علي ذلك ." } },
      { kind: 'reading', text: { en: "During his papacy, he ordained 53 bishops and many priests, he drew up Canons and laws concerning inheritance, and many other matters. He never took any money from anyone, nor he touched the revenue of the churches, or that of the religious endowments for the poor. When the governor of that time asked him for money, the nobles and people collected three hundred Dinars in gold and gave them to the governor on his behalf. He remained on the Episcopal Chair for fourteen years, two month and two days, then departed in peace.", ar: "ورسم في أيامه 53 أسقفا وكهنة كثيرين ووضع قوانين وأحكاما في المواريث وغيرها وتفاسير كثيرة ولم يعرف عنه أنه أخذ درهما واحدا من أحد . ولا وضع يده علي شيء من أموال الكنائس ولا أوقاف الفقراء . ولما طالبه حاكم ذاك الوقت بمال جمع له الأراخنة ألف مثقال ذهب ودفعوها عنه . وقضي علي الكرسي المرقسى أربعة عشر عاما وشهرين ويومين ثم تنيح بسلام صلاته تكون معنا ، ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-11",
    title: { en: "Baramouda 11", ar: "11 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of st. Theodora.", ar: "نياحة القديسة ثيؤدورة" } },
      { kind: 'reading', text: { en: "On this day, the pure and holy mother Theodora, departed. This holy woman was the only daughter of noble and Christian parents of Alexandria.\nHer parents Provided for her costly apparels and many gold and silver accessories, for they wished to give her in marriage. This Saint refused that, for she desired in her heart the worship of God and the strife for His Name's sake. She sold all what her father bought her, gave to the needy, and then built a church outside the city of Alexandria, towards the west.", ar: "في مثل هذا اليوم تنيحت القديسة الطاهرة الأم ثاؤذورا . هذه القديسة كانت ابنة وحيدة لوالدين من أغنياء الإسكندرية المسيحيين . فأحبا أن يزوجاها فأحضر لها الكثير من الحلي والملابس الغالية . فلم تقبل هذه القديسة ذلك لأنها كانت تميل بقلبها إلى عبادة الله والجهاد من أجل اسمه . وباعت كل ما أحضره لها والداها وفرقت منه علي المساكين ثم بنت كنيسة خارج الإسكندرية من الجهة الغربية وبعد ذلك قصدت الأب القديس اثناسيوس الرسولي (في القرن الرابع المسيحي) فقص شعرها ورهبنها خارج الإسكندرية فتنسكت نسكا زائدا وجاهدت جهادا روحيا حتى استحقت أن تنظر الإعلانات الإلهية ,ان تميز الملائكة من الشياطين وتعرف الأفكار وكان البابا أثناسيوس يفتقدها كثيرا بتعاليمه حتى أنه لما نفي كان يكاتبها من منفاه بالعظات المفيدة فثبتت في جهادها إلى آخر أيامها وعاصرت خمسة بطاركة وهم الكسندروس واثناسيوس وبطرس وتيموثاؤس وثاؤفيلس . وقد وضعت أقوالا كثيرة نافعة بعضها بالنعمة التي كانت فيها والبعض الأخر مما تعلمته من أولئك الأباء وسئلت مرة &quot; إذا تحدث إنسان مع آخر حديثا رديئا هل يقول له : اسكت أو ينتهره أو يميل عنه بسمعه ؟ &quot; فأجابت قائلة : &quot; كما أنك إذا وضعت أمامك أطعمة كثيرة جيدة وردية لا يمكنك أن تقول لواضعها ارفع هذا أو ذاك لأنه مضر بي . بل تتركها وتأكل ما يطيب لنفسك . هكذا لا يجب أن يقال شيء لمن يحادث غيره بحديث رديء بل يكفي الإنسان أن لا يدع سمعه يتلذذ بما سمع . &quot; وسئلت أيضا : بماذا يغلب الإنسان عدوه الشيطان ؟ &quot; فقالت &quot; بالصوم والصلاة والأتساع &quot; ولما أكملت جهادها تنيحت بسلام بالغة من العمر مائة سنة . صلاتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "Then she went to the holy father Abba Athanasius, the apostolic (Fourth century), who shaved her hair and made her a nun in one of the convents outside the city of Alexandria. She devoted herself to the ascetic life, fought the spiritual fight, and became worthy to see divine visions, distinguish angels from satan, and know the thoughts of the minds.", ar: "" } },
      { kind: 'reading', text: { en: "Pope Athanasius visited her often and instructed her with his teachings. When he was exiled, he sent her many letters full of valuable sermons, and she was steadfast in her strife until the end of her life. She was contemporary to five Patriarchs: Alexandros, Athanasius, Petros, Timotheos and Theophilos. She put down many useful sayings, some of them by the grace that was in her; the others were from what she learned from those fathers.", ar: "" } },
      { kind: 'reading', text: { en: "Once she was asked: \"If a man talked to another evil words, would he silence him, or rebuke him, or close the ears and not listen to him?\" She replied saying: \"If a man put in front of you a table with good and bad foods, you can not say to him \"Take this or that for it is harmful for me,' but you overlook it and eat what you desired, so nothing should be said to who speak bad words to others but it is enough that the man does not let his ears enjoy what he is hearing.\"", ar: "" } },
      { kind: 'reading', text: { en: "She was also asked: \"How can the human overcome his enemy Satan?\" She answered saying: \"With fasting, prayer, and humility.\"", ar: "" } },
      { kind: 'reading', text: { en: "When she finished her strife, she departed in peace and was one hundred years old.", ar: "" } },
      { kind: 'reading', text: { en: "Her prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. John, Bishop of Gaza.", ar: "تذكار انبا يوحنا اسقف غزة" } },
      { kind: 'reading', text: { en: "This day also marks the commemoration of the departure of Anba John, Bishop of Gaza.", ar: "في هذا اليوم تذكار نياحة أنبا يوحنا أسقف غزة شفاعته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "His intercession be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-12",
    title: { en: "Baramouda 12", ar: "12 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Alexander, Bishop of Jerusalem.", ar: "نياحة الكسندروس أسقف اورشليم" } },
      { kind: 'reading', text: { en: "On this day, the holy father Anba Alexander, Bishop of Jerusalem, departed. This holy father was Bishop of Cappadocia, and he came to the city of Jerusalem to receive the blessing of the holy places and then return to his country.", ar: "في مثل هذا اليوم تنيح الأب القديس الكسندروس أسقف أورشليم . هذا القديس كان أسقفا علي القبادوقية وجاء إلى أورشليم ليتبارك من الأمكنة المقدسة ثم يعود وكان القديس نركيسوس أسقف أورشليم (في القرن الثاني المسيحي) في ذاك الحين قد كبر وشاخ حتى جاوز مائة وعشر سنين . وكان قد عرض علي شعبه مرارا أن يتخلى عن الأسقفية فلم يقبلوا ذلك منه فلما قضي القديس الكسندروس واجب الزيارة وعزم علي العودة إلى القبادوقية مقر كرسيه . سمع أهل أورشليم صوتا سماويا يقول : &quot; أخرجوا إلى الباب الخارجي وامسكوه أول الداخلين ، وأقيموه أسقفا عليكم &quot; فخرجوا ووجدوا هذا الأب فامسكوه فامتنع محتجا بأنه لا يقدر أن يترك رعيته التي أقامه السيد المسيح لرعايتها فأعلموه بالصوت الذي سمعوه وأن هذا أمر الله . فقبل وكتب إلى أهل أبرشيته بما حصل واعتذر مصرحا لهم بإقامة أسقف عوضا عنه . وأقام بأورشليم يساعد أسقفها الأنبا نركيسوس نحو خمس سنوات وبعد نياحة نركيسوس استمر يرعى شعب أورشليم أحسن رعاية إلى أن قبض عليه مكسيميانوس الكافر وعذبه بأنواع العذاب ثم حبسه ، ولما ملك غرديانوس أطلق سراحه ولما مات وملك فيلبس أطلق بقية المعترفين ، ولكن عهد السلام لم يطل إلا قليلا لأن داكيوس قتل فيلبس وقبض علي زمام الملك ثم أثار الاضطهاد علي المسيحيين وأمسك هذا القديس مع كثيرين وعذبهم لاسيما هذا الأب فقد ضربه ضربا موجعا بدبابيس حادة إلى أن كسر أضلاعه . ثم أمر أن يجذب من رجليه ويطرح في السجن فظل به إلى أن أسلم نفسه الطاهرة بيد الرب ونال الملكوت المعد للقديسين . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: ", who was the Bishop of Jerusalem at that time (Second century - his departure on the first day of Baramhat), was advanced in age and had reached over 110 years. He often asked his people that he wished to retire from his See, but they refused. When St. Alexander finished his visit and decided to return to his Chair in Cappadocia, the people of Jerusalem heard a voice from heaven saying: \"Go to the gate of the city, and the first one to enter it, seize him and make him stay with Narcissus to assist him.\" When they went to the gate they met the Bishop Alexander, and they pleaded with him to stay with Abba Narcissus to assist him. He refused because he could not leave his flock that the Lord Christ had entrusted him with. They told him about the voice which they had heard from heaven and that it was God's Will. He accepted and wrote to the people of his parish what had happened, apologized, and allowed them to appoint another bishop in his place. He remained in Jerusalem, assisting its bishop Anba Narcissus, for about 5 years.", ar: "" } },
      { kind: 'reading', text: { en: "After the departure of St. Narcissus, he continued to shepherd the people of Jerusalem with the best of care, until Maximianus, the infidel, seized him, inflicted him with severe tortures of every kind, and then imprisoned him. When Gordianus reigned, he released him, and when he died and Philip reigned, he released the rest of the confessors. This father sat in quietness and peace until Decius rose, killed Philip, and reigned in his stead.", ar: "" } },
      { kind: 'reading', text: { en: "Decius afflicted the Christians exceedingly; he seized this holy father and many others, and tortured them, especially this father. He beat him cruelly with sharp pins until he broke his ribs, then commanded to drag him by his feet and throw him in prison. He remained there until he delivered his pure soul in the hand of the Lord, and received the kingdom which is prepared for the saints.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "التذكار الشهري لرئيس الملائكة الجليل ميخائيل" } },
      { kind: 'reading', text: { en: "", ar: "فى مثل هذا اليوم تحتفل الكنيسة بتذكار رئيس جند السماء الملاك الجليل ميخائيل الشفيع فى جنس البشر. شفاعته تكون معنا . آمين." } },
      { kind: 'heading', text: { en: "The Commemoration of St. Antonios, Bishop of Tamoui.", ar: "تذكار انبا انطونيوس اسقف طموه" } },
      { kind: 'reading', text: { en: "This day also marks the commemoration of St. Antonios, Bishop of Tamoui.", ar: "في هذا اليوم تذكار القديس أنطونيوس أسقف طمويه , صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-13",
    title: { en: "Baramouda 13", ar: "13 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of the Sts. Joshua and Joseph.", ar: "استشهاد انبا يشوع وانبا يوسف تلميذى القديس مليوس بجبل خوراسان" } },
      { kind: 'reading', text: { en: "On this day, the holy monks Anba Joshua and Anba Joseph were martyred. They were the disciples of in the mount of Khorasan, and their biography is mentioned in the , which is the day of martyrdom of their spiritual teacher Anba Melius.", ar: "في مثل هذا اليوم استشهد القديسان الراهبان الأنبا يشوع والأنبا يوسف ، تلميذا الأب القديس ميليوس بجبل خوراسان بالقرن الثالث الميلادى وسترد سيرتهما في اليوم الثامن والعشرين من هذا الشهر ، وهو اليوم الذي استشهد فيه معلمهما الروحاني الأنبا ميليوس . صلاتهما تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "Their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Yoannis the Seventeenth, the 105th. Patriarch of Alexandria.", ar: "نياحة انبا يوأنس بابا الإسكندرية ال105" } },
      { kind: 'reading', text: { en: "On this day also, the distinguished Pope and prudent pontiff, Anba Yoannis the seventeenth, 105th Patriarch of Alexandria, departed. The parents of this father were pious Christians from the city of Mallawy, in Upper Egypt.", ar: "في مثل هذا اليوم تنيح البابا الفاضل والحبر الكامل والحكيم العاقل البابا يوأنس السابع عشر البطريرك ( 105) من بطاركة الكرسي الإسكندري . وكان والدا هذا الأب مسيحيين تقيين من أهل ملوي في الصعيد فلما أتم السنة الخامسة والعشرين من عمره زهد العالم الزائل ومضي إلى دير القديس أنطونيوس وترهب هناك وكان اسمه عبد السيد وأنتقل منه إلى دير القديس الأنبا بولا بعد تعميره فأجهد نفسه في العبادة وانكب علي تثقيف نفسه فتعلم القراءة والكتابة لأنه لم يكن يعرفهما من قبل وتبحر بعد ذلك في دراسة الكتب المقدسة وبعد أن أجهد نفسه في الفضيلة والنسك وتزود بعلوم الكنيسة وكتبها اختاره الأباء الرهبان ليكون قسيسا لهم علي دير أنبا بولا فرسمه البابا يوأنس البطريرك (103 ) مع زميله مرجان الاسيوطي الذي صار فيما بعد البابا بطرس السادس البطريرك (104 ) الذي قبله ولما تنيح البابا بطرس السادس البطريرك ( 104 ) تشاور الأباء الأساقفة والكهنة والأراخنة في من يصلح للبطريركية ووقع اختيارهم علي تقديم هذا الأب فأحضروه من الدير إلى مصر وعملوا قرعة هيكلية - كما جرت العادة - وبعد القداسات التي أقيمت لمدة ثلاثة أيام تمت القرعة فسحب اسمه فرسم بطريركا في كنيسة الشهيد مرقوريوس أبي سيفين بمصر القديمة في يوم الأحد 6 طوبة سنة 1443 ش ( 12 يناير سنة 1727 م ) وبعد رسامته وقبل قراءة الإنجيل فتحوا باب مقبرة الأباء البطاركة ليأخذ - كالعادة - الصليب والعكاز من المتنيح سلفه فلما نزل المقبرة وأخذ الصليب , طقطق العظم في المقبرة في وجهه ففزع لوقته وأمر بأبطال هذه العادة قائلا : ان الصلبان أو العكاكيز كثيرة ثم أبطل هذا التقليد وكان الغرض منه أن يتعظ الخلف من مصير السلف حتى لا يغتر بالمركز ويتكبر فتكون رؤيته لمصير سلفه عظة وعبرة دائمة أمامه ولبث البابا بعد رسامته مقيما أسبوعا في مصر القديمة وبعدها توجه إلى القلاية البطريركية بحارة الروم ." } },
      { kind: 'reading', text: { en: "When he was 25 years old, he left this futile world and went to the monastery of St. Antonios. He became a monk there and his name was Abdel Sayed. Then he went to the monastery of Anba Paula, after its renovation. He exerted himself in worship, and educated himself. He learned reading and writing, for he was illiterate, then he thoroughly studied the holy books.", ar: "وأهتم هذا البابا بتشييد الكنائس والأديرة وترميمها وتكريسها فتم في مدة رئاسته تشييد كنيسة حسنة بدير القديس العظيم أنبا بولا أول السواح بجبل نصر . وكرسها بنفسه وكان في صحبته الأنبا ابرام أسقف البهنسا . وجماعة من الأراخنة . وعلي رأسهم الأرخن جرجس السروجي الذي قام بنفقات هذه الكنيسة وبعد هذا قام البابا ببناء كنيسة مقدسة ومائدة ومبان مختلفة بدير القديس الجليل أنبا أنطونيوس أبي الرهبان وكرسها أيضا بيده الكريمة ، ورسم هناك قمامصة وقسوسا وشمامسة وقام كذلك بالصرف علي هذه العمارات الأرخن المكرم جرجس السروجي وفي السنة التاسعة من رئاسته أي في سنة 1451 ش وردت الأوامر السلطانية بزيادة الضرائب في أرض مصر علي النصارى واليهود ثلاثة أضعاف مقدارها فكانت ضرائب الطبقة العالية أربعة دنانير والمتوسطة دينارين والأخيرة دينارا واحدا ثم زيدت بعد ذلك وفرضت علي فئة القسوس والرهبان والأطفال والفقراء والمتسولين ولم يستثنوا منها أحدا وكان الملتزمون بتحصيلها يحصرون سنويا من قبل السلطان فكانت أيامه شدة وحزن علي أرباب الحرف والفقراء" } },
      { kind: 'reading', text: { en: "After he exerted himself in asceticism and a virtuous life, studying the church subjects and its books, the fathers the monks chose him as a priest for them. Pope Yoannis, 103rd Patriarch ordained him along with his fellow Mourgan El-Assuity, who became, later on, Pope Petros VI, 104th Patriarch.", ar: "وحدث في أيامه غلاء عظيم أعقبه زلزال كبير بمصر أستمر في نصف الليل مقدار ساعة حتى تزعزعت أساسات الأرض وتهدمت المنازل وارتجف الناس ثم رحم الله شعبه ورفع عنهم هذه الشدائد المرة ." } },
      { kind: 'reading', text: { en: "When Pope Petros VI, 104th Patriarch departed, the fathers the bishops, priests, and lay leaders discussed who would be fit for the Patriarchal Chair. They chose this father among others, and brought them from the monasteries to Cairo. After they prayed the Divine Liturgy for three days, they cast the lot, which fell on this father.", ar: "ولما تنيح الأنبا خريستوذلو الثالث والثاني بعد المائة من مطارنة كرسي أثيوبيا في سنة 1742 م حضر إليه في السنة السابعة عشرة من رئاسته أي في سنة 1460 ش ( 1744 م ) جماعة من أثيوبيا يطلبون لهم مطرانا فرسم لهم الراهب يوحنا أحد قسوس دير أبينا العظيم أنبا أنطونيوس ودعاه يوأنس الرابع عشر في الاسم وعادوا به فرحين ." } },
      { kind: 'reading', text: { en: "He was ordained a Patriarch in the church of the martyr Mercurius Abu Saifain, in Old Cairo, on Sunday, the , 1443 A.M. (January 12th., 1727 A.D.). After his ordination and before the reading of the Gospel, they opened the door to the tomb of the fathers the Patriarchs, as the custom, for the newly elected Pope to go down and take the cross and staff from the hand of his departed predecessor. After he went down and took the cross, the bones in the tomb crepitated, and he was terrified, so he ordered to stop this practice, saying that the crosses and staffs were in abundance. The purpose of this custom was that the successor will take a lesson from his departed predecessor, so he would not be deceived by the position and become arrogant, and seeing the fate of his predecessor would be a lesson and example before him always. The Pope stayed after his enthronement a week in Old Cairo, then went to the Patriarchal residence in Haret El-Rum.", ar: "وقد عمر هذا البابا طويلا وعاش في شيخوخة صالحة راعيا شعبه الرعاية الحسنة ولما أكمل سعيه مرض قليلا وتنيح بسلام في يوم أثنين البصخة 13 برمودة سنة 1461 ش ( 20 أبريل سنة 1745 م ) بعد أن جلس علي الكرسي ثماني عشرة سنة وثلاثة أشهر وثمانية أيام ودفن بمقبرة الأباء البطاركة بكنيسة مرقوريوس أبي سيفين بمصر القديمة وقد كان معاصرا للسلطان أحمد الثالث والسلطان محمود الأول وخلا الكرسي بعده مدة شهر واحد عشر يوما . نفعنا الله ببركاته ,ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "This Pope dedicated himself to building churches and monasteries, their renovation and consecration. During his Papacy, a wonderful church was built in the monastery of Anba Paula, the first hermit in the Nemr Mount, and consecrated it himself. He was accompanied by Anba Ebraam, Bishop of El-Bahnasa, and an assembly of the notables. Among them was the archon Girgis El-Sourogy, who paid for the building of this church.", ar: "" } },
      { kind: 'reading', text: { en: "After that, Pope Youannis built a church, refectory, and other buildings in the monastery of the honorable saint Anba Antonios, the father of all monks. He consecrated it by his blessed hands and ordained there hegumens, priests, and deacons. The honorable archon Girgis El-Sourogy also paid for these buildings.", ar: "" } },
      { kind: 'reading', text: { en: "In the ninth year of his Papacy, in 1451 A.M., the Sultan ordered to raise the taxes for the Christians and Jews three folds. Later, these taxes were raised more and imposed over the monks, priests, children, poor, and beggars without exempting anyone, so the time of this father was difficult and sorrowful for the poor, professionals and trade workers.", ar: "" } },
      { kind: 'reading', text: { en: "During his time, there was also a great increase in prices and a severe earthquake shook Cairo in the middle of the night, which lasted for about an hour. The foundation of the earth violently shook, houses were destroyed, and people trembled then God Had mercy on his people and removed from them these bitter tribulations.", ar: "" } },
      { kind: 'reading', text: { en: "When Anba Khristozolo III, 102nd Metropolitan of the Chair of Ethiopia, departed, a group of Ethiopian lay leaders came to Pope Yoannis, in the 17th year of his Papacy, in 1460 A.M. (1744 AD.), and asked him to ordain for them a Metropolitan. He ordained for them the monk John (Youhanna), one of the priests of the monastery of our great father Anba Antonios, and called him Youannis XIV, and returned with joy with him.", ar: "" } },
      { kind: 'reading', text: { en: "This Pope lived long and lived until a good old age shepherding his flock with the best of care. When he finished his strife, he fell sick for a short illness and then departed in peace on the Monday of the Paschal week, the thirteenth of Baramoudah, year 1461 A.M. (April 20th., 1745 A.D.). He sat on the Chair 18 years, 3 months, and 8 days, and was buried in the tomb of the Patriarchs in the church of in Old Cairo. He was contemporary to the Sultan Ahmed III and the Sultan Mahmoud I. The Chair remained vacant one month and ten days after his departure.", ar: "" } },
      { kind: 'reading', text: { en: "His blessings be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of Dionisa (Denisa) the Deaconess and Medius the Martyr.", ar: "تذكار ديونيسة الشماسة وتذكار ميديوس الشهيد" } },
      { kind: 'reading', text: { en: "This day also marks the commemoration of St. Dionisa (Denisa), the deaconess who was appointed by the apostles and the commemoration of St. Medius the martyr.", ar: "في هذا اليوم تذكار القديسة ديونيسة الشماسة التي أقامها الرسل . وتذكار القديس ميديوس الشهيد , صلاة الجميع تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "Their prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-14",
    title: { en: "Baramouda 14", ar: "14 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of the Holy Father Anba Maximus The Fifteenth Pope of Alexandria.", ar: "نياحة البابا مكسيموس الاسكندرى 15" } },
      { kind: 'reading', text: { en: "On this day, that coincides with the ninth of April, 282 A.D., the holy father Anba Maximus, 15th Pope of Alexandria, departed. This father was born in Alexandria from Christian parents who raised and educated him well. He excelled in the Greek language. Then he learned the doctrine of the church and was a man that feared God.", ar: "في مثل هذا اليوم الموافق 9 أبريل سنة 282 م تنيح الأب القديس الأنبا مكسيموس الخامس عشر من باباوات الكرازة المرقسية . ولد هذا الأب بمدينة الإسكندرية من أبوين مسيحيين فعلماه وهذباه وقد تفقه في اللغة اليونانية ثم درس العلوم الدينية وكان رجلا يخاف الله فرسمه البابا ياروكلاس الثالث عشر شماسا علي كنيسة الإسكندرية ، ثم رسمه البابا ديونيسيوس الرابع عشر قسا ونظرا لتقدمه في الفضيلة والعلم أختاره الأباء الأساقفة لكرسي البطريركية بعد نياحة البابا ديونيسيوس وتولي الكرسي س في 12 هاتور ( 9 نوفمبر سنة 264 م ) , وبعد رسامته بزمن قليل وردت رسالة من مجمع إنطاكية تتضمن أسباب حرم بولس السميساطي والمشايعين له فقرأها علي كهنة الإسكندرية ثم حرر منشورا وأرسله مع رسالة المجمع إلى سائر بلاد مصر وأثيوبيا والنوبة يتضمن تحذرهم من بدعة بولس السميساطي وقد زالت بدعة هذا المبتدع بموته (كما جاء في مخطوط بشبين الكوم) في أيام هذا القديس ظهر إنسان من الشرق &quot; بلاد الفرس أسمه &quot; ماني &quot; قال هذا عن نفسه أنه الباراقليط روح القدس وجاء إلى أرض الشام وجادله أسقفها القديس ارشلاوس وأظهر ضلاله فترك الشام ورجع إلى بلاد الفرس : فأخذه بهرام الملك وشقه نصفين أما الأب مكسيموس فقد ظل مجاهدا وحارسا لرعيته ومثبتا لها بالعظات والإنذارات مدة سبع عشرة سنة وخمسة أيام وتنيح بسلام صلاته تكون معنا ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "Pope Heraclas, 13th Pope, ordained him deacon on the church of Alexandria. Then Pope Dionysius, 14th Pope, ordained him priest. Because of his advancement in virtues and knowledge, the fathers the bishops chose him for the Episcopal Chair after the departure of Pope Dionysius, and he was ordained on the twelfth of Hatour (November 9th., 264 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "Shortly after his enthronement, he received a letter from the council of Antioch, which included the grounds for excommunicating Paul of Samosata and his followers. He read it to the priests of Alexandria and issued a letter and sent it along with the letter of the council to all the cities of Egypt, Ethiopia, and Nuba. This was to warn them from the heresy of Paul of Samosata, which was abolished by the death of this heretic.", ar: "" } },
      { kind: 'reading', text: { en: "Pope Maximus fought and guarded his flock, confirmed them in the faith with sermons and admonitions for seventeen years and five days, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة الانبا باخوم الكبير" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم كانت نياحة الأنبا باخوم الكبير. صلاته تكون معنا و لربنا المجد دائما أبديا . آمين ." } }
    ],
  },
  {
    id: "synax-baramouda-15",
    title: { en: "Baramouda 15", ar: "15 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the church of St. Agabus, the Apostle.", ar: "تكريس كنيسة القديس أغابوس الرسول" } },
      { kind: 'reading', text: { en: "This day also, marks the commemoration of the consecration of the church of , one of the Seventy Apostles. He prophesied about the events that afflicted St. Paul saying: \"Thus says the Holy Spirit, 'So shall the Jews at Jerusalem bind the man who owns this belt, and deliver him into the hands of the Gentiles.'\" (Acts 21:10-11)", ar: "في هذا اليوم تذكار تكريس كنيسة القديس أغابيوس أحد السبعين رسولا الذي تنبأ بما أصاب القديس بولس الرسول (أعمال 21 : 10 و11) صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the first altar for St. Nicholas, Bishop of Mora for the Jacobite Christians.", ar: "تذكار تكريس أول هيكل للقديس نيقولاوس" } },
      { kind: 'reading', text: { en: "On this day, the church commemorates the consecration of the first altar that was built by the Jacobite Christians, who were residing in the land of Egypt for St. Nicholas, bishop of Mora. St. Nicholas was one of the fathers of the council of Nicea, the Three Hundred and Eighteen. This altar was built in the church of the saint Anba Shenouda, to the east of the city.", ar: "في مثل هذا اليوم تعيد الكنيسة بتذكار تكريس أول هيكل بناه النصارى اليعاقبة (ربما يقصد السريان الموجودين بمصر المقيمون بأرض مصر) ، للقديس نيقولاوس أسقف ميرا أحد آباء مجمع نيقية الثلاثمائة وثمانية عشر . وكان بناؤه بالكنيسة التي علي اسم القديس الأنبا شنوده شرقي البحر . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Alexandra, the Empress.", ar: "نياحة القديسة الكسندرة الملكة" } },
      { kind: 'reading', text: { en: "On this day also, St. Alexandra, the Empress, Emperor Diocletian's wife, departed. When the great martyr, St. George deluded Emperor Diocletian that he would worship his idols, the Emperor embraced his head and brought him into his royal palace.", ar: "في مثل هذا اليوم تنيحت القديسة الكسندرة الملكة ، زوجة الملك دقلديانوس . وذلك أنه لما خدع الشهيد العظيم جاورجيوس الملك دقلديانوس بأنه سيسجد لآلهته قبل رأسه وأدخله إلى داره فصلي القديس ثم قرأ جزءا من المزامير أمام الملكة وفسر لها ما قرأه ثم أوضح لها الوهية السيد المسيح فدخل كلامه في قلبها وآمنت بالسيد المسيح له المجد . ولما وقف القديس جاورجيوس أمام الأصنام ونادي باسم السيد المسيح تحطمت فخزي الملك ومن معه من ذلك . ولما عاد إلى قصره وأخبر الملكة بذلك قالت له : أما قلت لك لا تعاند الجليليين فان الههم قوي فغضب الملك جدا وعذبها كثيرا ثم ألقاها في السجن حيث تنيحت بسلام . صلاتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "The Saint prayed and read some of the Psalms before Empress Alexandra and interpreted to her what he read. He explained to her the Divinity of the Lord Christ. His words entered her heart and she believed in the Lord Christ, to Whom is the glory.", ar: "" } },
      { kind: 'reading', text: { en: "When the Saint stood before the idols, he called the Name of the Lord Christ, and the idols were destroyed. The Emperor and those with him were humiliated. When the Emperor returned to the palace and told the Empress what had happened, she told him: \"Did I not tell you not to set yourself against the Galilean, for their God is strong and powerful?\" Diocletian became extremely raged, tortured her severely, then threw her in prison where she departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "Her prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Mark (Marcus) VI, the 101st. Patriarch.", ar: "تذكار نياحة البابا مرقس السادس البطريرك" } },
      { kind: 'reading', text: { en: "On this day also, of the year 1372 A.M. (April 20th., 1656 A.D).), Pope Mark (Marcus) VI, 101st Patriarch of Alexandria, departed. He was known as Marcus El-Bahgoury. He was from Bahgourah, and became a monk in the monastery of St. Antonios.", ar: "في مثل هذا اليوم من سنة 1372 ش ( 20 أبريل 1656 م ) تنيح البابا مرقس السادس البطريرك الإسكندري ( 101) وهو يعرف بمرقس البهجوري لأنه من بهجورة وترهب بدير القديس أنطونيوس . ولما تنيح البابا متاؤس الثاني البطريرك المائة اتفق المعلم بشارة المتقدم علي الأراخنة في ذلك العصر هو وجماعة المصريين علي رسامة هذا الأب ، وترأس احتفال الرسامة الأنبا خرستوذولو أسقف بيت المقدس في يوم الأحد 15 برمودة سنة 1362 ش ( 20 أبريل سنة 1646 م ) ودعي مرقس السادس وبعد رسامته وقع خلاف كبير بينه وبين المعلم بشارة . ومن أعمال هذا البابا المأثورة أنه أصدر أمرا للرهبان بمنعهم من الإقامة في العالم وبعودتهم جميعا إلى أديرتهم فغضب الرهبان من هذا الأمر ولم يوافقوا عليه وامتنعوا عن العمل به وحرك الشيطان عدو الخير أحد الرهبان المدعو قدسي فرفع للباشا عريضة ضد البطريرك ادعي فيها بأنه يمد الناس بالفلقة ويقتلهم بها فاهتم الوالي بالشكوى وأمر بكشف الحقيقة وعند التحقيق أنكر الراهب موضوع الشكوى وظهرت براءة البابا من التهمة الواردة في عريضة الشكوى ولكنه غرم بغرامة دفعها عنه أكابر الدولة وفي 21 طوبة سنة 1365 ش نودي بأن لا يركب النصارى خيولا ولا يلبسوا قفاطين حمراء ولا طواقي جوخ حمراء ولا مراكيب وإنما يلبسون قفاطين زرقاء طول الواحدة عشرون ذراعا ." } },
      { kind: 'reading', text: { en: "When Pope Matteos III, 100th Pope, departed, the archon Beshara, the lay leader of that time, agreed with the people on ordaining this father. Anba Khristozolo, Bishop of Jerusalem, headed the celebration of the enthronement, on Sunday, the fifteenth of Barmoudah, 1362 A.M. (April 20th. 1646 A.D.), and was called Marcus VI. After his ordination, a vast dispute took place between him and the archon Beshara.", ar: "وسافر البطريرك إلى الصعيد وأقام هناك أربع سنوات جمع أثناءها أموالا طائلة وكان أحمق جدا حتى ضج من أعماله سائر الناس والأساقفة والقسوس والاراخنة واستمرت العداوة قائمة بينه وبين المعلم بشارة حتى عاد إلى مصر فاصطلح معه واستقام أمره بعد ذلك . ومن أعماله أنه قام ببناء قاعة الصلاة بدير الراهبات بكنيسة العذراء بحارة زويلة عثر علي خمس أوان من الزجاج ملآنة بالميرون المقدس كما أنه عثر أيضا علي زقين آخرين وهي من ذخائر العصور القديمة فوضع الكل بأعلى مخزن المهمات الكائن فوق مدفن البابا يؤنس الثالث عشر البطريرك (94) بكنيسة العذراء بحارة زويلة ." } },
      { kind: 'reading', text: { en: "From his famous achievements, he issued an order preventing the monks from living in the world, ordering them to return to their monasteries. The monks were raged because of this order, did not consent to it, and refrained from obeying it. Satan, the enemy of the good, moved one of the monks called Kodsy, to write a petition to the Governor (Basha), accusing the Pope that he tortured the people and killed them. The Governor ordered an investigation to uncover the truth. During the inquiry, the monk denied writing the petition. The Pope was exonerated from the accusations that were in the complainant petition, but he was ordered to pay a heavy fine which was paid by the lay leaders of the country.", ar: "وقد تنيح هذا البابا يوم 15 برمودة سنة 1272 ش ( 20 أبريل سنة 1656 م ) ودفن بكنيسة أبي سيفين بمصر القديمة بعد أن أقام علي الكرسي عشرة أعوام كاملة وقد عاصر كلا من السلطان إبراهيم الأول والسلطان محمد الرابع وخلا الكرسي بعده أربع سنوات وسبعة شهور وستة عشر يوما نفعنا الله ببركاته ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "On the , 1365 A.M., an order was issued to prevent Christians from riding horses, wearing red caftans (A long sleeved outer garment), and red broadcloth skull caps. However they were to wear blue caftans thirty feet long.", ar: "" } },
      { kind: 'reading', text: { en: "The Patriarch went to Upper Egypt and stayed there for four years, during which he collected much money and was foolish in his conduct, to the point that all the people, bishops, priests, and lay leaders, were exasperated. The dispute, existed between him and the archon Beshara, went on until he returned to Cairo. He then reconciled with him, and his behavior was straighten after that. He built the prayer hall in the convent of the church of the virgin in Haret Zeewaila in Cairo.", ar: "" } },
      { kind: 'reading', text: { en: "Pope Marcus departed on the 15th of Barmoudah, 1372 A.M. (April 20th. 1656 AD.). He was buried in the church of in Old Cairo, after he stayed on the Chair for ten full years. He was a contemporary to El Sultan Ibrahim I and El Sultan Mohammed IV, and the Chair was vacant for four years, seven months and sixteen days after him.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-16",
    title: { en: "Baramouda 16", ar: "16 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Antipas, Bishop of Pergamos.", ar: "استشهاد أنتيباس تلميذ يوحنا الرسول أسقف مدينة برغامس" } },
      { kind: 'reading', text: { en: "On this day, St. Antipas, bishop of Pergamos, was martyred. He was a disciple of St. John the evangelist (Rev. 2).", ar: "في مثل هذا اليوم استشهد القديس أنتيباس أسقف برغامس كان تلميذا للقديس يوحنا الإنجيلي (رؤ 2 ) وحدث أنه لما شرع دوميتيانوس في اضطهاد القوم وقتلهم بلغة أن النصارى يقولون &quot; ان ملكهم هو المسيح (ورد في مخطوط بشبين الكوم &quot; انه أرسل إلى أورشليم واستدعي أولاد يهوذا بن يوسف وأتي بهم مقيدين إلى روما وسألهم عن ملك المسيح فأجابوه أن ملكه سماوي وأن المسيح في السماء وهو عتيد يأتي في آخر الدهر ليدين الأحياء والأموات ويجازي كل واحد كأعماله &quot;) فخاف لما سمع هذا القول وترك اضطهادهم وأمر بإكرامهم ." } },
      { kind: 'reading', text: { en: "Domitianus started persecuting and killing the Christians because he heard, that they were saying, that Christ was their God and King. This Saint was one of them. He was tortured severely, but adhered more to the faith. During his imprisonment, sent him a message to comfort and strengthen him. In his message, he called him faithful priest and good shepherd.", ar: "ثم تولي بعده واليا أخراً فاضطهد المسيحيين وقتل منهم كثيرين وكان من جملتهم هذا القديس وقد عاقبه عقابا شديدا فازداد إلا ثباتا في الإيمان ، ولما أودعه السجن أرسل له القديس يوحنا الإنجيلي رسالة مملوءة تعزية دعاه فيها الكاهن الآمين والراعي الصالح وأخيرا وضعه الملك في ثور مصنوع من نحاس وأوقد النيران تحته حتى أسلم روحه الطاهرة بيد الرب وأخذ المؤمنون جسده ووضعوه بكرامة في الكنيسة صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Finally, the Emperor placed him in a bull of brass and lighted fire under him until he delivered up his soul in the hand of the Lord. The believers took his body and placed it with great honor in the church.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-17",
    title: { en: "Baramouda 17", ar: "17 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. James the Apostle Brother of St. John the Apostle.", ar: "استشهاد القديس يعقوب بن زبدى الرسول" } },
      { kind: 'reading', text: { en: "On this day, St. James the Apostle, the son of Zebedee, and the brother of St. John, the Apostle, was martyred. After he had preached the Gospel in Judea and Samaria, he went to Spain. He preached the Gospel there, and its people believed in the Lord Christ. He returned to Jerusalem and pursued his ministry.", ar: "في مثل هذا اليوم استشهد القديس يعقوب الرسول أخي القديس يوحنا الرسول إبنا زبدى. وذلك أنه بعدما نادي في اليهودية والسامرة ، سافر إلى أسبانيا وبشر أهلها بالإنجيل فآمنوا بالسيد المسيح وعاد إلى أورشليم وباشر خدمته . وكان يوصي شعبه بتقديم الصدقات إلى الفقراء والمساكين والضعفاء فوشوا به لدي هيرودس فاستدعاه وقال له أنت الذي تدعو أن لا يعطوا الجزية لقيصر بل يصرفوها علي الفقراء والكنائس ثم ضربه بالسيف فقطع رأسه ونال إكليل الشهادة وقد روى أكليمندس الإسكندري من رجال الجيل الثاني قائلا ان الجندي الذي قبض علي القديس لمار رأى شجاعته علم أنه لا بد من حياة أخري أفضل . فطلب الصفح من القديس فقال له حييت يا ولدي ثم اعترف الجندي بالمسيحية فنال إكليل الشهادة (أع 12 : 1 ، 2 ) مع الرسول سنة 44 م ويقال أن جسده نقل إلى أسبانيا حيث يعتبر يعقوب الكبير رسولها ثم اعتقل أيضا القديس بطرس الرسول وأودعه السجن حتى ينتهي الفصح ويقتله (أع 12 : 3 و 4 ) . فضربه ملاك الرب . وذلك أنه لبس في يوم معين الحلة الملوكية وجلس علي كرسي الملك وجعل يخاطبهم فصرخ الشعب هذا صوت اله لا صوت إنسان &quot; . ففي الحال ضربه ملاك الرب لأنه لم يعط المجد لله فصار يأكله الدود ومات (أع 12 : 21 –23) أما جسد القديس يعقوب فقد أخذه المؤمنون وكفنوه ودفنوه عند الهيكل. صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "He always advised his flock to give alms to the poor, the needy, and the weak. They accused him before Herod who called him and asked him: \"Are you the one that instigating the people not to give the taxes to Caesar but to give it to the poor and the churches?\" Then he smote him with the sword, cutting off his head, and St. James received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "Clement of Alexandria, from the fathers of the second century, said: \"The soldier that seized the Saint, when he saw his courage, he realized that there must be a better life and asked the Saint for his forgiveness. Then the soldier confessed Christianity and received the crown of martyrdom (Acts 12:1,2) along with the Apostle in the year 44 A.D.\"", ar: "" } },
      { kind: 'reading', text: { en: "Because Herod saw that it pleased the Jews, he proceeded further to seize Peter also. So when he had apprehended him, he put him in prison, and delivered him to four squads of soldiers to keep him, intending to bring him before the people after Passover. (Acts 12:3-4)", ar: "" } },
      { kind: 'reading', text: { en: "So on a set day Herod, arrayed in royal apparel, sat on his throne and gave an oration to them. And the people kept shouting, \"The voice of a god and not of a man!\" Then immediately an angel of the Lord struck him because he did not give glory to God. And he was eaten by worms and died. (Acts 12:21-23)", ar: "" } },
      { kind: 'reading', text: { en: "As of the body of St. James, the believers took it, shrouded it, and buried it by the Temple. It was said that the body of St. James was translated to Spain, where James the elder considered to be its Apostle.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-18",
    title: { en: "Baramouda 18", ar: "18 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Arsenius, Slave of St. Sousnyous.", ar: "استشهاد أرسانيوس مملوك سوسيتيوس" } },
      { kind: 'reading', text: { en: "On this day St. Arsenius, the slave of St. Sousnyous, was martyred. When Emperor Diocletian was torturing St. Sousnyous, St. Sousnyous father told the Emperor that Sousnyous had a slave, whose name is Arsenius and that he worshiped Christ and denounced the worship of the idols.", ar: "في مثل هذا اليوم استشهد القديس ارسانيوس مملوك القديس سوسنيوس وقد شكا والد هذا القديس إلى دقلديانوس الغلام أرسانيوس وقال انه يعبد المسيح وينكر عبادة الأصنام فأحضره الملك وسأله عن معتقده فأعترف بألوهية السيد المسيح ووبخ الملك أيضا علي تركه عبادة الإله الحقيقي وتمسكه بعبادة الأوثان . فاستشاط الملك غضبا وأمر بضرب عنقه أمام سيده ونال إكليل الشهادة . صلاته تكون معنا لربنا المجد دائما , آمين" } },
      { kind: 'reading', text: { en: "The Emperor brought the slave and asked him about his belief. Arsenius confessed the Divinity of the Lord Christ, and also admonished the Emperor for deserting the worship of the true God and his insistence on worshiping the idols. The Emperor became furious and ordered him to beheaded him before his master, and thus he received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد اوسابيوس وأبامون الشماس" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهاد اوسابيوس وأبامون الشماس. صلاتهما تكون معنا و لربنا المجد دائما أبديا آمين ." } }
    ],
  },
  {
    id: "synax-baramouda-19",
    title: { en: "Baramouda 19", ar: "19 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Simeon the Armenian, Bishop of the country of Persia and 150 with him.", ar: "استشهاد سمعان الارمنى أسقف الفرس و150 شهيد معه" } },
      { kind: 'reading', text: { en: "On this day, St. Simeon the Armenian, Bishop of the country of Persia, and 150 with him, were martyred. This Bishop lived during the reign of Sapor (Shapur), the son of Hormiz, king of Persia, who was unjust and oppressive to the Christians.", ar: "في مثل هذا اليوم استشهد القديس سمعان الأرمني أسقف بلاد فارس ومائة وخمسون معه . كان هذا القديس في زمان سابور بن هرمز ملك الفرس . الذي كان كثير الجور والظلم علي المسيحيين ويعاملهم بقسوة . فكتب اليه هذا القديس رسالة قال له ان الذين ابتاعهم السيد المسيح بدمه قد تخلصوا من عبودية البشر ولا يجوز أن يصيروا عبيدا للذين يتعدون الشريعة . فلما قرأ الملك هذه الرسالة غضب جدا واستحضره ثم قيده بالسلاسل وألقاه في السجن فوجد هناك بعض المحبوسين يعبدون الشمس فعلمهم ووعظهم فأمنوا بالسيد المسيح وأقروا بذلك أمام الوالي فقطع رؤوسهم ثم استحضر القديس من السجن ومعه مائة وخمسين شخصا . وقطع رؤوسهم جميعا ونالوا إكليل الشهادة." } },
      { kind: 'reading', text: { en: "This Saint wrote a letter to king Sapor and told him: \"Those whom the Lord Christ has bought with His honorable Blood had rid themselves from the servitude of men, and it is not conceivable for them to be in servitude for those who transgress the Law.\" When the king had read this letter, he became exceedingly wrath. He brought him, bound him with chains, and cast him into the prison. In prison, he found prisoners who worshipped the sun. The Saint rebuked them, taught them, and they believed in the Lord Christ.", ar: "" } },
      { kind: 'reading', text: { en: "They confessed their faith before the king, who brought the Saint from the prison, because he preached them the faith. The king ordered to cut off the heads of the Saint and the 150 persons with him, and they received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the blessed Youhanna (John) Abu Nagaah El-Kabeer.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, of the year 719 A.M., the blessed Youhanna (John) Abu Nagaah El-Kabeer, was martyred. He was one of the nobel Copts in the tenth and eleventh centuries. He was the head scribe in his time, as he was the lay leader during the reign of Al-Hakim Be-Amr Ellah the Fatimid Caliph. This great elder was a contemporary to Pope Philotheos, 63rd Patriarch, who was enthroned on March 28th. 979 A.D. and departed on November 8th. 1003 A.D.", ar: "" } },
      { kind: 'reading', text: { en: "Youhanna was a devout Christian, righteous, virtuous, charitable, and loving to the church. He was zealous in the Orthodox faith. When Al-Hakim Be-Amr Ellah completed the extermination of the people close to him and the leaders of the army, he turned to the notables and chiefs of the scribes. He called ten of them and offered them to adopt Islam. Youhanna, who was their head, was called first. Al-Hakim told him: \"I want you to leave your faith and adopt my faith, the Islam. I will make you my minister to manage the affairs of my kingdom.\" Youhanna replied saying: \"Give me a chance until tomorrow to deliberate the matter with myself\"", ar: "" } },
      { kind: 'reading', text: { en: "Youhanna went to his house, called his friends, informed them with what had happened, and told them: \"I am ready to die in the Name of the Lord Christ, and my reason for asking for the delay, not to deliberate the matter with myself but to see you and my family, to bid you and my family farewell, and to commend you and them. Now my brothers, do not ask for this vain glory, for you will loose the eternal glory of the Lord Christ Who satisfied us with the richness of the world, and now with His mercy, He had called us to the Kingdom of Heaven, so strengthen your hearts.\"", ar: "" } },
      { kind: 'reading', text: { en: "His golden words, which were full of wisdom, influenced those who heard them, strengthened their hearts, and they decided to die in the Name of the Lord Christ also. He made a great feast for them, and then they went to their homes. The next morning, Youhanna went to Al-Hakim Be-Amr Ellah who asked him: \"O Nagaah, have you decided?\" Youhanna (John) replied saying \"Yes\". The Caliph asked: \"Which way have you decided?\" Youhanna answered steadfastly and with courage: \"Remaining in my faith.\"", ar: "" } },
      { kind: 'reading', text: { en: "The Governor attempted with all ways of persuasion and threatening to make him forsake Christianity. John was steadfast as a rock; nothing shook him away from the Christian faith, and the Governor could not with all his powers make him renounce the faith of his fathers.", ar: "" } },
      { kind: 'reading', text: { en: "When the Governor failed with Youhanna, he ordered to remove his clothes, be tied to the squeezing wheels, and be beaten. They beat him five hundred lashes on his delicate body, and his flesh was torn and his blood flew as water. The whips that were used were made of cow hides; even the mighty ones could not bear one lash from it on their bodies, much less, this gentle branch.", ar: "" } },
      { kind: 'reading', text: { en: "Then the Governor ordered to beat him up to one thousand lashes. After he was beaten three hundred more lashes, he said as his Master: \"I am thirsty.\" They stopped beating him and informed the Governor who told them: \"Water him after you tell him forsake your faith.\" When they came to him with the water and told him as the Caliph ordered, Youhanna replied with pride and dignity: \"Take the water back to him, for I do not need it, because My Master Jesus Christ had watered me and quenched my thirst.\" The people who were standing around testified that they saw at this moment water dripping from his beard. When he said that, he delivered up his soul.", ar: "" } },
      { kind: 'reading', text: { en: "When they told the tyrant Governor about his death, he ordered them to beat the dead body to complete the one thousand lashes, and thus he was martyred, and received the crown of martyrdom that was prepared for him by the Great King Jesus Christ.", ar: "" } },
      { kind: 'reading', text: { en: "The History of the Patriarch did not mention the day that he was martyred, but El-Makrizi in his manuscripts said: \"The Vizier Fahd Ibn Ibrahim, one of the ten men and the companion of Youhanna Ibn Nagaah, was slained in the nineteenth of Barmoudah, 719 A.M. (April 14th., 1003 A.D.)\" The martyrdom of the blessed Youhanna Ibn Nagaah was mentioned in the History of the Patriarchs, before the mentioning of the martyrdom of the Vizier Fahd Ibn Ibrahim. Youhanna, in the feast that he made for his friends and kinfolks among whom were the other nine chosen ones, did not mention the account of the martyrdom of the Vizier Fahd in what he said during the feast. Accordingly, the martyrdom of this Saint was on the same day of the martyrdom of the Vizier fahd.", ar: "" } },
      { kind: 'reading', text: { en: "His blessings be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the Vizier Abu Elaala Fahd ibn Ibrahim and his companions.", ar: "" } },
      { kind: 'reading', text: { en: "This day also marks the commemoration of the martyrdom of the Elder the Vizier Abu Elaala Fahd Ibn Ibrahim, who was distinguished in the later half of the tenth century and early the eleventh century. He was also contemporary to Pope Philotheos, 63rd Patriarch, and from the Fatimid Caliphs, Al Emam Al-Azeez Be Allah, and his son Al-Hakim Be-Amr Allah.", ar: "" } },
      { kind: 'reading', text: { en: "He was an Orthodox Archon, adhered to his faith, faithful to his church, and charitable. During his life, he never turned down anyone who asked him. Whenever he went through the streets riding and one asked him, he would extend the sleeve of his cloak and the one asking would find much good in it, and that to hide his virtue of giving.", ar: "" } },
      { kind: 'reading', text: { en: "This vizier was one of the powerful and influential men of the government during the Fatimid Rule. Al-Hakim Be-Amr Allah appointed him head of all the scribes and department heads. He built the church of the martyr St. Mercurius in the present monastery of Anba Rowais, which was known then by Dair El-Khandaq.", ar: "" } },
      { kind: 'reading', text: { en: "It is documented in the History of the Patriarchs that when Al-Hakim Be-Amr Allah wanted to make the notable Coptic scribes apostatize their faith, the Vizier Fahd was one of the ten that was chosen for that purpose. He brought him and told him: \"You know that I have chosen and appointed you ahead of all the men in my government, then listen to me and be with me in my religion, so I will promote you more than what you are in now and be like a brother to me.\" When he did not answer him, he ordered his neck to be cut off and to burn his body. The fire remained burning for three days and the body did not burn, and his right hand that he extended to give alms, was sound at all the time as the fire never touched it.", ar: "" } },
      { kind: 'reading', text: { en: "It was mentioned also in the book of El-Khetat El-Tawfikiah that the Vizier Abu Elaala Fahd Ibn Ibrahim was discussing the affairs of the government with the head of the army, El-Housain Ibn Gawhar, and El-Hakim was luring him to apostatize his faith with many promises. When Fahd refused, he ordered his head to be cut off and to burn his body but God protected his body from burning. He was buried in the southern corner of the church of St. Mercurius, which he built in Dair El-khandaq. El-Makrizi wrote in his manuscripts: \"Fahd Ibn Ibrahim was killed after he had remained as a chief minister of the government for five years, nine months and twelve days.\"", ar: "" } },
      { kind: 'reading', text: { en: "God had took revenge severely from the wicked people that discredited Abu Elaala Fahd before the Caliph and changed his heart against him. Twenty-nine days after the departure of Fahd, the wicked man, Aly Ibn Omar Ibn El-addas, was killed, then his companion, Taher Mahmoud Ibn El-Nahawy, was killed.", ar: "" } },
      { kind: 'reading', text: { en: "The church also commemorates the rest of the ten chief ministers that the Governor asked them to apostatize their faith. When they refused and disobeyed him, he ordered to torture them. They were beaten with whips, and when the beating became cruel, four of them became Muslims, one of them died the same night, and the other three returned to their Christian Faith after the end of the time of persecution. The rest departed while they were being tortured and received the crown of martyrdom\r\nand acquired the eternal life.", ar: "" } },
      { kind: 'reading', text: { en: "Their blessings be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of Daoud (David), the Monk.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, Daoud Ibn Ghobrial El-Bargy, the monk, was martyred. He was from the village of Berkit Karmout. He was tortured severely but did not forsake the faith, and he received the crown of martyrdom in the year 1099 A.M.", ar: "" } },
      { kind: 'reading', text: { en: "Their intercession be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-20",
    title: { en: "Baramouda 20", ar: "20 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Babnuda (Paphnute).", ar: "استشهاد القديس ببنودة من دندرة" } },
      { kind: 'reading', text: { en: "On this day, St. Babnuda (Paphnute), who was from Dandara (Dendereh), was martyred. This Saint was a hermit monk. The angel of the Lord appeared to him and told him to put on the priesthood vestments and go appear before , the governor.", ar: "في مثل هذا اليوم استشهد القديس ببنوده الذي من دندره هذا القديس كان راهبا متوحدا . فظهر له ملاك الرب وقال له البس ثياب الخدمة الكهنوتية ، واذهب لمقابلة أريانوس الوالي . الذي كان قد رسا بمركبه علي دندره يجد في طلب هذا القديس . فجاء إليه وصرخ في وجهه بأعلى صوته قائلا &quot; أنا نصراني مؤمن بالسيد المسيح &quot; فلما عرفه الوالي أنه ذلك المتوحد ، الذي يجد في طلبه عذبه عذابا كثيرا ثم كبله بالحديد وطرحه في سجن مظلم . فأشرق عليه نور سماوي وظهر له ملاك الرب وشفاه من جراحاته وعزاه وكان في المدينة رجل اسمه كيرلس وزوجته وابنته واثنا عشر صبيا فوعظهم القديس وثبتهم فاستشهدوا جميعا بقطع رؤوسهم ونالوا إكليل الشهادة وغضب الوالي عليه فأمر بأن يعلق في رقبته حجر ويطرح في البحر فنال إكليل الشهادة .صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Arianus arrived with his ship and embarked by the city of Dandara, looking for that Saint. The Saint came to Arianus and cried out in his face with a loud voice, saying: \"I am Christian, and I believe in the lord Christ.\" When the Governor knew that he was the anchorite for whom he sought, he ordered him to be tortured severely. He chained him with iron fetters and cast him in a dark prison. A heavenly light shone upon him and an angel of the Lord appeared to him, healed his wounds, and comforted him.", ar: "" } },
      { kind: 'reading', text: { en: "There was in the city a man, whose name was Kyrillos, with his wife, his daughter, and twelve young men. The Saint preached them and confirmed them in faith. They were all martyred by cutting of their heads, and they received the crown of martyrdom. The Governor was raged of him and ordered to hang a rock in his neck and cast him in the sea, and St. Babnuda received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد السعيد يوحنا أبو نجاح الكبير" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم من سنة 719 للشهداء استشهد السعيد الذكر يوحنا أبو نجاح الكبير وقد كان من عظماء الأقباط في الجيلين العاشر والحادي عشر للميلاد . وكان كبير الكتاب المباشرين في عصره . كما كان مقدم الأراخنة في عهد الحاكم بأمر الله الخليفة الفاطمي . وكان هذا الشيخ الكبير يعاصر البابا فيلوثاؤس البطريرك ( 63 ) الذي تولي الكرسي من 28 مارس سنة 979 م إلى 8 نوفمبر سنة 1003 م ." } },
      { kind: 'reading', text: { en: "", ar: "وكان يوحنا هذا مسيحيا تقيا وبارا محسنا كبيرا ، ومحبا للكنيسة غيورا علي الإيمان الأرثوذكسي . ولما انتهي الحاكم بأمر الله من إفناء خواصه ومقدمي جيشه ، عاد إلى مقدمي الأراخنة ورؤساء الكتاب فأخذ منهم عشرة وعرض عليهم الإسلام وكان أولهم يوحنا أبو نجاح رئيس المقدمين ، فأحضره إليه وقال له &quot; أريد أن تترك دينك وتعود إلى ديني وأجعلك وزيري فتقوم بتدبير أمور مملكتي &quot; فأجابه يوحنا قائلا &quot; أمهلني إلى غد حتى أشاور نفسي &quot; فأمهله وأطلقه فمضي يوحنا إلى منزله وأحضر أصدقاءه وعرفهم ما جرى له مع الخليفة وقال لهم &quot; أنا مستعد أن أموت علي اسم السيد المسيح وان غرضي من طلب المهلة إلى الغد لم يكن لمشاورة نفسي بل قلت هذا حتى اجتمع بكم وبأهلي فأودعكم وأوصيكم&quot; ، ثم أوصاهم قائلا &quot;والآن يا أخوتي لا تطلبوا هذا المجد الفاني فتضيعوا عليكم مجد السيد المسيح الدائم الباقي فقد اشبع نفوسنا من خيرات الأرض وهوذا برحمته قد دعانا إلى ملكوت السموات فقووا قلوبكم &quot; ." } },
      { kind: 'reading', text: { en: "", ar: "وقد كان من أثر كلامه الذهبي المملوء حكمة أن تشددت قلوب سامعيه أجمعين وعزموا علي أن يموتوا علي اسم السيد المسيح ، ثم صنع لهم في ذلك اليوم وليمة عظيمة وأقاموا عنده إلى المساء ثم مضوا إلى منازلهم ." } },
      { kind: 'reading', text: { en: "", ar: "وفي الصباح مضي يوحنا إلى الحاكم بأمر الله فقال له الخليفة : &quot; يا نجاح ، أتري هل طابت نفسك ؟ &quot; أجابه يوحنا قائلا : &quot; نعم &quot; قال الخليفة : &quot; علي أية قضية ؟ &quot; قال يوحنا بشجاعة وثبات : بقائي علي ديني &quot; ." } },
      { kind: 'reading', text: { en: "", ar: "فاجتهد الحاكم بكل أنواع الترغيب والوعيد أن ينقله من النصرانية فكان يوحنا كالصخرة لا يتزعزع ، وثبت متمسكا بالإيمان المسيح ولم يقو الحاكم - مع ما أوتي من قوة - علي أن يزحزحه عن دين آبائه ." } },
      { kind: 'reading', text: { en: "", ar: "ولما فشل الحاكم أمام يوحنا أمر بنزع ثيابه وأن يشد في المعصرة ويضرب ، فضربوه خمسمائة سوط علي ذلك الجسم الناعم حتى أنتثر لحمه وسأل دمه مثل الماء وكانت السياط المستعملة في الضرب مصنوعة من عروق البقر لا تقوي الجبابرة علي احتمال سوط منها علي أجسامهم فكم يكون الحال في هذا العود الرطب .ثم أمر الحاكم بأن يضرب إلى تمام الآلف سوط فلما ضرب ثلاثمائة أخري قال مثل سيده &quot; أنا عطشان &quot; فأوقفوا عنه الضرب وأعلموا الحاكم بذلك فقال &quot; اسقوه بعد أن تقولوا له أن يرجع عن دينه &quot; فلما جاءوا إليه بالماء وقالوا له ما أمرهم به الخليفة ، أجابهم يوحنا بكل أباء وشمم قائلا : &quot; أعيدوا له ماءه فآني غير محتاج إليه لأن سيدي يسوع المسيح قد سقاني وأطفأ ظمأى &quot; وقد شهد قوم من الأعوان وغيرهم ممن كانوا هناك أنهم أبصروا الماء يسقط في هذه اللحظة من لحيته . ولما قال هذا اسلم الروح فأعلموا الخليفة الجبار بوفاته فأمر أن يضرب وهو جثة هامدة حتى تمام الآلف سوط وهكذا تمت شهادته ونال الإكليل المعد له من الملك العظيم يسوع المسيح ولم يذكر تاريخ البطاركة اليوم الذي استشهد فيه إلا أن المقريزي في خططه قال : &quot; ان الرئيس فهد بن إبراهيم وهو أحد العشرة وزميل يوحنا بن نجاح قتل في 8 جمادى الآخر سنة 393 هجرية الموافق 19 برمودة سنة 719 ش و 14 أبريل سنة 1003 م &quot; ." } },
      { kind: 'reading', text: { en: "", ar: "وقد جاء استشهاد السعيد الذكر يوحنا بن نجاح في تاريخ البطاركة ، قبل ذكر استشهاد الرئيس فهد بن إبراهيم كما أن يوحنا في وليمة أصدقائه وأهله الذين كان من بينهم التسعة المختارون الآخرون - لم يذكر خبر استشهاد هذا القديس في نفس اليوم الذي استشهد فيه الرئيس فهد فيما تكلم به أثناء الوليمة وعلي ذلك يكون استشهاد هذا القديس في نفس اليوم الذي استشهد فيه الرئيس فهد." } },
      { kind: 'heading', text: { en: "", ar: "استشهاد الرئيس أبو العلا فهد بن إبراهيم وزملائه" } },
      { kind: 'reading', text: { en: "", ar: "تحتفل الكنيسة بتذكار الشيخ الرئيس أبو العلا فهد بن إبراهيم الذي نبغ في النصف الأخير من الجيل العاشر وأول الجيل الحادي عشر وقد عاصر أيضا البابا فيلوثاوس البطريرك (63) كما عاصر من الملوك الخلفاء الفاطميين الأمام العزيز بالله وابنه الحاكم بأمر الله ." } },
      { kind: 'reading', text: { en: "", ar: "وكان أرخنا أرثوذكسيا متمسكا بدينه مخلصا لكنيسته كثير الإحسان فلم يرد في حياته سائلا تقدم إليه حتى أنه كان يجتاز الشوارع راكبا فيليفاه طالب الصدقة فيمد إليه كم جبته فيجد فيه السائل خيرا جزيلا وذلك إمعانا في إخفاء عطائه ." } },
      { kind: 'reading', text: { en: "", ar: "وكان هذا الرئيس من أكابر رجال الدولة في العهد الفاطمي حتى أن الحاكم بأمر الله قدمه علي جميع الكتاب وأصحاب الدواوين ، وأنشا الرئيس أبو العلاء كنيسة الشهيد مرقوريوس بدير أنبا رويس الحالي الذي كان معروفا وقتئذ بدر الخندق" } },
      { kind: 'reading', text: { en: "", ar: "وجاء في تاريخ البطاركة أنه لما أراد الحاكم بأمر الله أن يجعل كبار الكتاب الأقباط يتخلون عن دينهم كان الرئيس فهد من بين الرؤساء العشرة الذين اختارهم لهذا الغرض فأحضره بين يديه وقال له : &quot; أنت تعلم أني اصطفيتك وقدمتك علي كل من في دولتي فاسمع مني وكن معي في ديني فأرفعك أكثر مما أنت فيه وتكون لي مثل أخ &quot; فلم يجبه إلى قوله فأمر أن يضرب عنقه وأحرق جسده بالنار وظلت النار مشتعلة ثلاثة أيام ولم يحترق وبقيت يده اليمني التي كان يمدها للصدقة في كل وقت سليمة كأن النار لم تكن منها البتة ." } },
      { kind: 'reading', text: { en: "", ar: "وجاء في كتاب الخطط التوفيقية أن الرئيس أبو العلاء فهد بن إبراهيم كان ينظر في أمر المملكة مع قائد القواد الحسين بن جوهر وكان الحاكم بأمر الله يرغبه في ترك مذهبه بوعود عظيمة فلم يقبل فقطع رقبته وأمر بحرق جسمه ولكن الله حماه من الاحتراق ودفن في الركن القبلي من كنيسة القديس مرقوريوس إلى شيدها في دير الخندق ." } },
      { kind: 'reading', text: { en: "", ar: "وذكر المقريزي في خططه : وقتل فهد بن إبراهيم بعد أن أستمر في الرئاسة خمس سنين وتسعة أشهر وأثنا عشر يوما ." } },
      { kind: 'reading', text: { en: "", ar: "وقد انتقم الله شر انتقام من الأشرار الذين سعوا بالرئيس أبي العلاء فهد لدي الخليفة وغيروا قلبه عليه فقد كان علي بن عمر بن العداس هو الذي حرك قلب الحاكم بأمر الله عليه فلم يمض علي وفاة الرئيس فهد 29 يوما حتى قتل علي ثم قتل شريكه طاهر محمود بن النحوي" } },
      { kind: 'reading', text: { en: "", ar: "وتحتفل الكنيسة أيضا بباقي الرؤساء العشرة الذين لما طالبهم الحاكم بترك دينهم لم يفعلوا ذلك ولم يطيعوه فأمر بتعذيبهم فضربوا بالسياط ولما تزايد عليهم الضرب أسلم منهم أربعة مات أحدهم في ليلته بعينها وأما الثلاثة الآخرون فانهم بعد انقضاء زمان الاضطهاد عادوا إلى دينهم المسيحي وأما الباقون فقد ماتوا وهم يعذبون ونالوا إكليل الشهادة استحقوا الحياة الدائمة." } },
      { kind: 'heading', text: { en: "", ar: "استشهاد داود الراهب" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد داود الراهب (ورد ذلك في مخطوط شبين الكوم بن غبريال البرجي من بركة قرموط) وقد عذب كثيرا ولم ينكر الإيمان ونال إكليل الشهادة سنة 1099 للشهداء . شفاعة الجميع تكون معنا ولربنا المجد دائما . أمين" } }
    ],
  },
  {
    id: "synax-baramouda-21",
    title: { en: "Baramouda 21", ar: "21 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Lady the Theotokos.", ar: "التذكار الشهري لوالدة الاله القديسة مريم العذراء" } },
      { kind: 'reading', text: { en: "On this day, we celebrate the commemoration of the Lady Virgin Mary, the Mother of God the Word.", ar: "فى مثل هذا اليوم نعيد بتذكار السيدة العذراء الطاهرة البكر البتول الذكية مرتمريم والدة الإله الكلمة أم الرحمة، الحنونة شفاعتها تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "Her intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Hierotheos, of Athens.", ar: "نياحة القديس بروثاوس قس أثينا" } },
      { kind: 'reading', text: { en: "On this day also, St. Hierotheos (Berutawos) of Athens, departed. This father was one of the learned men in the city of Athens. He met the Apostle St. Paul, and many discussions took place between them which led to his belief on the Apostle's hand. He baptized him, taught him the Ordinances and Law of the church, and then ordained him a priest for this city. He frequently visited St. Dionysius the Areopagite, who was also one of the learned men in Athens.", ar: "في مثل هذا اليوم تنيح القديس بروثاؤس اللاتيني هذا الأب كان من علماء مدينة أثينا فاجتمع بالقديس بولس الرسول . وجرت بينهما مباحثات أدت به إلى أن يؤمن علي يده فعمده وعلمه كل الفرائض المسيحية ورسمه قسا علي تلك المدينة وقد اجتمع هذا القديس بالقديس ديونيسيوس الأريوباغي وكان هذا من علما أثينا أيضا . وقد حضر هذا القديس نياحة السيدة العذراء وقام في وسط التلاميذ وعزاهم بكلمات منظومة أنشدت بالآلات الموسيقية ورد جماعة من اليهود والأمم إلى معرفة السيد المسيح (عن مخطوط شبين الكوم ) وأراد الشعب رسامته أسقفا فلم يقبل وقال &quot; ليتني أقدر علي القيام بواجبات القسيسية &quot; ولما أكمل سعيه الصالح انتقل إلى الرب الذي أحبه صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "This Saint was present at the time of the , and he stood in the midst of the apostles and comforted them with spiritual songs and hymns which he sang accompanied with musical instruments.", ar: "" } },
      { kind: 'reading', text: { en: "He converted many Jews and Gentiles to the knowledge of the Lord Christ. When the people wished to ordain him a bishop, he refused saying: \"I just wish to be able to perform the duties of a priest.\" Having finished his good strife, he went to the Lord Whom he loved.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نوة الخماسين ، شم النسيم : شرقية ساخنة يومان" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة ." } },
      { kind: 'reading', text: { en: "", ar: "في فصل الربيع هناك رياح محلية تعرف (باسم الخماسين ) وهي رياح رملية شديدة الحرارة تهب من الجهات الجنوبية علي الدلتا ويرجع سبب هبوبها إلي مرور انخفاضات جوية آتية من الغرب. ويبدأ الانخفاض الخماسيني في التكوين فوق واحة سيوة ثم يتحرك شرقاً صوب الدلتا فيشتد هبوب الرياح الجنوبية التي تجلب معها عواصف الرمال والغبار وهي لها أثار سيئة علي النبات بخاصة في محافظتي الجيزة والقليوبية ." } },
      { kind: 'reading', text: { en: "", ar: "وتعرف هذه الرياح في السودان باسم الهبوب، وفي ليبيا باسم القبلي، وفي المغرب باسم السيروكو، والسولانو وفي شبة الجزيرة العربية السموم." } }
    ],
  },
  {
    id: "synax-baramouda-22",
    title: { en: "Baramouda 22", ar: "22 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Alexander I, 19th Pope of the See of St. Mark.", ar: "نياحة البابا الكسندروس الاسكندرى ال19" } },
      { kind: 'reading', text: { en: "On this day also of the year 44 A.M. (April 17th., 328 A.D.) the holy father Pope Alexander (Alexandros), 19th Pope of the See of St. Mark, departed.", ar: "في مثل هذا اليوم من سنة 44 ش ( 17 أبريل سنة 328 م ) تنيح الأب القديس البابا الكسندروس التاسع عشر من باباوات الكرازة المرقسية وقد ولد هذا البابا بمدينة الإسكندرية من أبوين مسيحيين . ونشا في خدمة الكنيسة فرسمه البابا مكسيموس أغنسطسا ، والبابا ثاؤنا شماسا ، والبابا بطرس قسا . وكان بكرا طاهرا ولما دنا وقت استشهاد البابا بطرس دخل إليه الكسندروس في السجن هو والأب أرشلاؤس الذي صار بطريركا بعده وسألاه أن يحل أريوس من الحرم فأعاد حرمه أمامهما وعرفهما أن السيد المسيح قد ظهر له في رؤيا وأمره بذلك وأعلمه بجلوس الأب أرشلاؤس بطريركا بعده وبعد الأب أرشلاؤس يجلس البابا الكسندروس وأوصي بهذا كهنة الإسكندرية وأمرهم بعدم قبول أريوس وألا يكون له معهم شركة ." } },
      { kind: 'reading', text: { en: "This Pope was born in the city of Alexandria from Christian parents, and he grew up in serving the church. Pope Maximus ordained him a reader, Pope Theonas ordained him a deacon. Pope Peter (Petros the Seal of the Martyrs) ordained him a priest, and he was virgin and chaste.", ar: "ولما جلس البابا أرشلاؤس علي الكرسي وقبل أريوس لم يمكث سوي ستة أشهر وتنيح ولما جلس البابا الكسندروس تقدم إليه أعيان الشعب وسألوه أن يقبل أريوس فأبي وزاده حرما وقال لهم أن البابا بطرس أمره هو والبابا أرشلاؤس بذلك ولما خالف البابا أرشلاؤس هذا الآمر نزعه الله سريعا من كرسي الرئاسة ." } },
      { kind: 'reading', text: { en: "When the time of Pope Petros (Peter) martyrdom drew near, Alexander and father Archelaus, who became Patriarch before him, went to him in prison, and asked him to lift the excommunication from Arius. Anba Petros excommunicated Arius again in their presence, and informed them that the Lord Christ had appeared to him and ordered him not to receive him again and that father Archelaus will be Patriarch after him and after Abba Archelaus, Pope Alexander will be ordained. He commanded that to the priests of Alexandria and ordered them not to accept Arius, and to have no fellowship with him.", ar: "وبعد هذا نفي أريوس من البلاد فذهب إلى الملك قسطنطين الكبير وتظلم إليه من هذا البابا فأمر باجتماع مجمع الثلاثمائة وثمانية عشر في نيقية فاجتمع تحت رئاسة البابا الكسندروس الذي جادله وأفحمه ثم حرمه هو ومن يقول بقوله ونطق بالأمانة مع بقية الآباء ووضع القوانين والشرائع والأحكام التي لا تزال بين أيدي المؤمنين إلى يومنا هذا . وبعد أن رتب صوم الأربعين وعيد الفصح عاد إلى كرسيه غالبا . وكانت مدة جلوسه علي كرسي الكرازة المرقسية خمس عشرة سنة وتسعة أشهر وعشرين يوما . صلاته تكون معنا ولربنا المجد دائما , آمين" } },
      { kind: 'reading', text: { en: "When Pope Archelaus sat on the Chair and received Arius, he only lived for six months and died. When Pope Alexandros sat, the lay leaders came and asked him to receive Arius, but he refused and added curses to what were already upon him. He told them: \"Pope Petros had commanded Pope Archelaus and myself to do that, and when Pope Archelaus had received Arius, God speedily removed him from his office.\"", ar: "" } },
      { kind: 'reading', text: { en: "Pope Alexander expelled Arius from the country. Arius went to and complained of the unjust treatment of this Pope. Emperor Constantine assembled the Ecumenical Council of the Three Hundred and Eighteen in the city of Nicea. The council was presided by Pope Alexander. He debated with Arius and revealed his denial of Christ, then excommunicated him and those who follow his belief.", ar: "" } },
      { kind: 'reading', text: { en: "Alexander, along with the rest of the fathers, uttered the Creed, and drew up the Canon, the Law, and the Statutes that are still in the hands of Christians until this day. After he put down regulations for Lent and the feast of Easter, he returned to his Chair, victorious and triumphant. He shepherded his flock with the best of care. He sat on the throne of the See of St. Mark for 15 years, 9 months and 20 days, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Mark 11, 49th Pope of the See of St. Mark.", ar: "نياحة البابا مرقس الثانى" } },
      { kind: 'reading', text: { en: "On this day also, of the year 535 A.M. (April 17th., 819 A.D.), the blessed father Pope Mark (Marcus), 49th Pope of the See of St. Mark, departed.", ar: "في مثل هذا اليوم من سنة 535 ش (17 أبريل سنة 819 م ) تنيح الأب المغبوط مرقس التاسع والأربعين من باباوات الكرازة المرقسية . هذا البابا كان من أهل الإسكندرية ، بكرا طاهرا عالما فاضلا . وقد رسمه البابا يوحنا شماسا فقسا فكان كل من يسمعه يطرب بصوته وبحسن نغماته في الصلاة وسلم إليه البابا البطريرك تدبير البطريركية ولم يكن يعمل شيئا إلا بعد أخذ رأيه ، وعندما البسه الاسكيم المقدس في الهيكل . صاح أحد الشيوخ قائلا : هذا الشماس الذي اسمه مرقس سيستحق أن يجلس علي كرسي أبيه مرقس لما تنيح البابا يوحنا أجمع الأساقفة علي اختياره بطريركا فهرب إلى البرية ولكنهم لحقوا به وأحضروه ورسموه بطريركا في يوم 2 أمشير سنة 515 ش ( 26 يناير 799م ) فأهتم بشؤون الكنائس وعمر ما خرب منها ورد أرباب البدع إلى الرأي القويم وأبرأ مرضي كثيرين وأخرج من بعضهم الشياطين وقال لبعضهم أن ما أصابكم حدث نتيجة تجاسركم علي التناول من الأسرار المقدسة بجهل ، فاحفظوا نفوسكم منذ الآن من الكلام الرديء الذي يخرج من أفواهكم . وفي أيامه استولي العرب علي جزائر الروم وسبوا كثيرين من نسائهم وأولادهم وآتو بهم إلى الإسكندرية وشرعوا في بيعهم فجمع من المؤمنين مالا علاوة علي ما كان عنده من أموال الأديرة ودفع في سبيل إنقاذهم وإطلاق حريتهم ومبلغ ثلاثة آلاف دينار وكتب لهم أوراق عتقهم وزود من رجع إلى بلاده بالمال اللازم له وزوج من بقي منهم وصار يعتني بهم وأهتم هذا الأب بكنيسة المخلص التي بالإسكندرية وجددها فأحرقها بعض الأشرار فعاد وجددها ثانية ." } },
      { kind: 'reading', text: { en: "This Pope was from Alexandria, and he a was chaste, learned, and honorable man. Pope John ordained him a deacon, and he was an eloquent speaker. His voice was sweet and all those who heard him rejoiced in him. The Pope handed him the administration of the papal place, and he did nothing without his advice. When Pope John put on him the garb of monks in the monastery, one of the elder monks shouted saying: \"This deacon whose name is Mark shall, rightly and fittingly sit upon the throne of his father .\"", ar: "ولما أراد الرب نياحته مرض قليلا فقام بخدمة القداس وتناول الأسرار الإلهية ثم ودع الأساقفة الذين كانوا عنده وتنيح بسلام بعد أن أقام علي الكرسي عشرين سنة وشهرين واحد وعشرين يوما صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When pope John departed, the bishops unanimously agreed to choose him Patriarch. He fled to the desert, but they caught up with him, brought him back, and enthroned him Patriarch on the , 515 A.M. (January 26th., 799 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "He tended to the churches needs, and restored those that were in a ruinous state. He returned many of the heretics to the Orthodox faith, healed many of the sick, and cast out, of many of them, devils. He told them: \"What had happened to you was because you dared to partake of the Holy Mysteries with irreverence, so keep yourselves henceforward from the evil words that come out of your mouth.\"", ar: "" } },
      { kind: 'reading', text: { en: "In his days, the Muslim Arabs conquered the Greek Isles, captured many of their women and children, brought them to Alexandria, and started to sell them. The Pope gathered money from the believers, and beside the funds of the monasteries that he had, he was able to pay three thousand Dinars to save and free them. He wrote for them bills of manumission and set them free. He provided those who wished to return to their country with whatever they needed, and those who wished to stay, he gave them in marriage and protected them. He took thought for the church of the Redeemer in Alexandria and restored it, but some evil men burned it, so he restored it again.", ar: "" } },
      { kind: 'reading', text: { en: "When the Lord willed to give him rest, he became sick. He prayed the Divine Liturgy and partook of the Holy Mysteries. He bade the bishops that were present farewell and departed in peace after staying on the Chair 20 years, 2 months and 21 days.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Michael 11, 53rd Pope of the See of St. Mark.", ar: "نياحة البابا خائيل الاسكندرى" } },
      { kind: 'reading', text: { en: "On this day also, of the year 567 A.M. (April 17th., 851 A.D.), the holy father Pope Michael (Khail), 53rd Pope of Alexandria, departed.", ar: "في مثل هذا اليوم من سنة 567 ش ( 17 أبريل سنة 851 م ) تنيح الأب القديس البابا خائيل الثالث والخمسون من باباوات الإسكندرية كان هذا الأب راهبا قديسا وقد رسم قمصا علي دير القديس الأنبا يحنس وكان ذا سيره صالحة فاختاره بطريركا وأعتلي كرسي البطريركية في 24 هاتور سنة 566 ش (20 نوفمبر سنة 849 م ) . ولما حلت أيام الصوم المقدس صعد إلى البرية ليقضيها هناك . فتذكر حياته الأولى في البرية فسأل الله ببكاء وتضرع قائلا أنت تعلم يارب أني لا أزال أهوي الوحدة وأني ليس لي طاقة علي هذا المركز الذي أنا فيه فقبل الرب دعاءه وتنيح بسلام بعد عيد الفصح . بعد أن قضي علي الكرسي سنة واحدة وأربعة أشهر وثمانية وعشرين يوما . صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "This father was a righteous monk, and he was ordained hegumen for the monastery of the saint Abba John. Because of his good conduct, they chose him Patriarch, and he was enthroned in the 566 A.M. (November 20th., 849 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "When the Holy Fast came, he went to the desert of Scetis to keep the fast there. He remembered his earlier life in the wilderness, so he asked God with tears and supplication saying: \"O God, you know how much I love solitary life and I have no aptitude for the position that I am in.\" The Lord accepted his petition and he departed in peace after the feast of Passover. He stayed on the Chair one year, four months and twenty-eight days.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Isaac (Ishaq), of Hourin.", ar: "نياحة القديس اسحق الهوزيني" } },
      { kind: 'reading', text: { en: "On this day the holy father Anba Isaac (Ishaq) departed. He was born in the city of Hourin - Shabas, from unblemished parents. His father's name was Abraham, and his mother's name was Susannah. His mother departed when he was a child, and his father, shortly after, married another wife. In those days there was a famine, and his step-mother hated him. She only gave him a little bread, which he gave to the shepherds that he worked with. He fasted until sunset, although he was only five years old. When his father knew that, he went to see him to inquire into that. Knowing the matter, before his father came to him, he tied up three pieces of mud in his cloak, so that his father might think when he saw them from far that they were bread. When his father came and unrolled the cloak, he found three pieces of bread. The shepherds who were present testified that the boy had given them all what he had of bread, and others saw him tieing the pieces of mud in his cloak. His father marvelled and glorified God.", ar: "في مثل هذا اليوم تنيح الأب القديس الأنبا أسحق . وقد ولد بمدينة هورين من أعمال شباس من أبوين طاهرين وكان اسم أبيه إبراهيم وأمه سوسنة وقد توفيت وتركته صغيرا . ثم تزوج أبوه بعد ذلك واتفق أن حدث في البلاد غلاء عظيم وكانت امرأة أبيه تبغضه فلا تعطيه من الخبز إلا القليل . فكان يفرقه علي الرعاة الذين كان يرعى معهم ويبقي هو صائما إلى الغروب مع أن عمره كان وقتئذ ابن خمس سنين وشعر أبوه وحل طرف العباءة وجد قطع الطين خبزا وشهد الحضور بأن الصبي قد فرق ما كان معه من الخبز كما رآه البعض وهو يربط قطع الطين هذه في طرف عباءته فتعجب والده ومجد الله لما كبر الصبي مضي وترهب عند رجل قديس اسمه الأنبا ايليا وأقام عنده مدة وبعد نياحة الأنبا ايليا مضي إلى جبل برنوج وأقام عند شيخ يدعي الأنبا زخارياس وكان أبوه يجد في البحث عنه فلما عثر عليه عند القديس وطلب منه الذهاب معه أشار عليه معلمه أن يطيع والده ويعود معه فعاد ومكث حتى مات أبوه ففرق كل ما تركه له وانفرد في مكان بناه لنفسه يبعد قليلا عن المدينة وداوم علي النسك والعبادة إلى أن تنيح بسلام فدفنوه في محل عبادته . ونسي مكانه وبعد سنين أراد الرب إظهار جسده فظهر نور عظيم علي قبره . رآه جماعة من الحصادين مدة ثلاثة أيام متوالية . فجاء المؤمنون ورفعوا جسده ووضعوه علي جمل وساروا به حتى وصلوا إلى مكان بين هورين ونشرت فوقف الجمل عن السير . فعلموا أن هذا بإرادة الرب وبنوا في هذا المكان كنيسة . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When Isaac grew up, he went and became a monk with a righteous man whose name was Elias, and he lived with him for many years. After the departure of Anba Elias, he went to the mount of Barnug and lived with an old man whose name was Anba Zacharias. His father went about everywhere trying to find him. When he found his son living with St. Zacharias, he asked him to return with him. His teacher Anba Zacharias advised him to obey his father and return with him.", ar: "" } },
      { kind: 'reading', text: { en: "He returned and stayed until his father's departure. He distributed all what his father left him to the poor and needy. He then built for himself a place out side the city, where he dwelt there alone. He went on asceticism and worship until he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "They buried him in his place of worship, and the place was forgotten. After many years, God willed to reveal his body, and a great light appeared above his grave, which was seen by reapers for three consecutive days. The believers came, took his body, laid it on a camel, and journeyed with it until they came to a place between Horein and Nashrat. The camel stopped, knelt down, and would not get up again. They knew that this was the Lord's Will and they built a church for him in that place where they placed the body with great honor.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-23",
    title: { en: "Baramouda 23", ar: "23 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. George Prince of the Martyrs.", ar: "استشهاد مار جرجس الرومانى" } },
      { kind: 'reading', text: { en: "On this day, of the year 307 A.D., the great among the martyrs St. George, was martyred. He was born in Cappadocia; his father's name was Anastasius, and his mother's name was Theobaste. When he was twenty years old, his father died, and he went to Emperor Diocletian to take over his father's position. He found that the Emperor had apostatized the faith and ordered the worship of idols. George was sorrowful, and he gave all his wealth to the poor and needy and set free his slaves.", ar: "في مثل هذا اليوم من سنة 307 م استشهد القديس العظيم في الشهداء مار جاؤرجيوس . وقد ولد بالقبادوقية من أب أسمه أنسطاسيوس وأم تدعي ثاؤبستا . ولما صار ابن عشرين سنة مات والده . فذهب إلى دقلديانوس ليتقلد وظيفة والده فوجد أن الملك قد كفر وأمر بعبادة الأصنام فحزن وفرق كل ماله وأعطاه للمساكين وصرف غلمانه وتقدم إلى الملك معترفا بالسيد المسيح له المجد وكان ذلك بعد أن رأي منشورات الإمبراطور فصرخ في وسطهم قائلا &quot; إلى متي تصبون غضبكم علي المسيحيين الأبرار وتكرهون الذين عرفوا الإيمان الحقيقي علي أن يتبعوا الديانة التي أنتم في شك منه لأنه غير حقيقية ؟ فأما أن تؤمنوا بهذه الديانة الحقيقية أو علي الأقل لا تقلقوا بحماقة أولئك المتمسكين بها . فأشار الملك إلى مفنانيوس ، أحد وزرائه لتهدئته فقال له : &quot; من علمك هذه الجرأة &quot; فأجابه : &quot; هو الحق &quot; ثم بدأ يشرحه له ، فتدخل الملك وأخذ يذكره بالرتب التي أنعم بها عليه ويعده بالمزيد منها إذا جحد مسيحه فرفض بآباء هذه العروض الزائلة ولم يلتفت إليها فعذبه كثيرا وكان الرب يقويه ويشفي جميع جراحاته ." } },
      { kind: 'reading', text: { en: "When he saw the edict of the Emperor against the Christians, he became raged and tore it. They took him before the Emperor, and he cried in their middest saying: \"For how long you shall pour your anger against the innocent Christians, and force those who know the true faith to adopt the faith that you are in doubt of because it is fraudulent? So, either you believe on this true faith, or at least do not disturb with foolishness those who are steadfast in it.\" The Emperor asked Mephnanius, one of his ministers, to pacify and persuade him. He asked him: \"Who taught you to be daring like this.\" The Saint answered: \"It is the truth,\" then started to explain it to him. The Emperor interrupted, reminding the Saint with the ranks that he bestowed on him, and promised him with more if he denied his Christ. The Saint refused with pride all these vain propositions. The Emperor tortured him severely, but the Lord strengthened him and healed all his wounds.", ar: "ولما حار الملك في تعذيبه أستحضر ساحرا أسمه أثناسيوس وهذا أحضر كأسا ملأنا وتلا عليه من أقواله السحرية ، وقدمه للقديس فشربه بعد أن رسم عليه علامة الصليب ، فلم ينله آذى ، مما جعل أن الساحر نفسه يؤمن بالسيد المسيح ، ونال إكليل الشهادة فاغتاظ الملك وأمر بعصر جاؤرجيوس حتى يسلم الروح فطرحوه خارج المدينة ولكن السيد المسيح أقامه حيا وعاد هذا الشهيد إلى المدينة فرآه الجميع وآمن بسببه في تلك اللحظة ثلاثة آلاف وسبعمائة نفس . فأمر دقلديانوس بقطع رؤوسهم جميعا فنالوا إكليل الشهادة ." } },
      { kind: 'reading', text: { en: "When the Emperor was weary of torturing him, he brought a magician, whose name was Athanasius, who gave the Saint a cup full of poison to drink. St. George made the sign of the cross over the cup then drank it. When no harm came upon him, the magician believed in the Lord Christ, and received the crown of martyrdom. The Emperor became raged and ordered to squeeze him until he delivered up his soul, and they cast his body out side the city.", ar: "وكان بحضرة دقلديانوس بعض من الملوك فقالوا للقديس &quot; نريد أن تجعل هذه الكراسي تورق وتثمر &quot; . فصلي القديس إلى السيد المسيح فاستجاب طلبه . وأخذه مرة إلى مقبرة وطلبوا إليه أن يقيم من بها من الموتى ، فصلي إلى السيد المسيح فأقامهم الرب وبعد أن تحدثوا إليهم عادوا فرقدوا . وقدمت له امرأة فقيرة ابنها وكان أعمي وأصم وأخرس فصلي إلى السيد المسيح ورشم الطفل بعلامة الصليب فشفي من جميع أمراضه . وكان دقلديانوس مستمرا في تعذيبه فلما تعب من ذلك ومل صار يلاطفه ، ويعده أن يزوجه من أبنته إذا بخر للآلهة فخادعه ، جاؤرجيوس وأوهمه أنه قبل ذلك ففرح وأدخله إلى قصره وبينما كان يصلي سمعته الملكة وهو يقرأ المزامير فطلبت إليه أن يشرح ما كان يقوله . فبدأ يفسر لها كل الأمور من أول خلقة العالم إلى تجسد السيد المسيح فدخل كلامه في قلبها وآمنت بالمسيح له المجد ." } },
      { kind: 'reading', text: { en: "The Lord Christ raised him up, and the Saint returned to the city. When the people saw him, three thousand and seven hundred souls believed. The Emperor ordered to cut off their heads and they received the crown of martyrdom.", ar: "وكان الملك قد أمر أن ينادوا في المدينة باجتماع الناس ليروا جاؤرجيوس يبخر لآلهة الملك , فلما اجتمع جمع كبير عند الأصنام وقف جاؤرجيوس وصرخ في الأصنام باسم الرب يسوع مخلص العالم . ففتحت الأرض فاها وابتلعت جميع الأصنام فخزي الملك ومن معه ودخل حزينا إلى قصره فقالت له الملكة : ألم أقل لك &quot; لا تعاند الجليليين لان إلههم قوي ؟ &quot; فعلم أن جاؤرجيوس قد أمالها هي الأخرى إلى أيمانه ودفعه الغيظ إلى أن أمر بتمشيط جسمها وقطع رأسها فنالت إكليل الشهادة . وأخيرا رأي دقلديانوس أن يضع حدا لتلك الفضائح التي تلحقه فقرر قطع رأس القديس جاؤرجيوس فنال إكليل الشهادة وأخذ أحد المسيحيين جسده ولفه في أكفان فاخرة ومضي به إلى بلده وبنوا علي اسمه كنيسة عظيمة شفاعته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "When St. George stood before Emperor Diocletian, along with seventy kings that were sitting around him, they asked the Saint: \"We wish you to make these chairs that we are sitting on to put forth leaves, and bear fruit.\" The Saint prayed to the Lord Christ, the Lord accepted his supplication and the chairs put forth leaves and bore fruit.", ar: "" } },
      { kind: 'reading', text: { en: "They took him once to a cemetery and asked him to raise the dead therein. He prayed to the Lord Christ. The Lord raised them and after they talked to them, they returned to their graves and died.", ar: "" } },
      { kind: 'reading', text: { en: "A poor woman, brought her son, who was blind, deaf and dumb, he prayed to the Lord Christ then made the sign of the cross over him, and he was healed right away.", ar: "" } },
      { kind: 'reading', text: { en: "Diocletain, during all that, went on torturing St. George, until he was weary and bored of that. He started to be pleasant to the Saint and promised to give him his daughter in marriage if he would offer the incense to his gods. The Saint pretended that he accepted his offer, and the Emperor rejoiced and brought him into the royal palace. While St. George was praying the Psalms, the Empress heard him and asked him to explain to her what he had said. He began to interpret to her all the events from the creation of the world to the Incarnation of the Lord Christ, and his words entered her heart and she believed in the Lord Christ, to Whom is the Glory.", ar: "" } },
      { kind: 'reading', text: { en: "The Emperor ordered to call upon all the men of the city to gather, in order to see Saint George offering the incense to the Emperor's gods. When multitude gathered by the idols, Gawargios (George) stood and cried at the idols in the Name of the Lord Christ the Savior of the world. The earth opened its mouth and swallowed all the idols. The Emperor and all those who were with him were ashamed and he returned to his palace full of fury and wrath. The Empress told him: \"Didn't I tell you not to oppose the Galileans, for their God is strong and mighty?\" The Emperor was exceedingly wrath with her, for he knew that St. George had brought her also to his faith. The Emperor with rage ordered to comb her body with a steel comb, then cut off her head, and she received the crown of martyrdom. Finally, Diocletian decided to put an end to the humiliation that befell him, so he ordered to cut off the head of St. George, and he received the crown of martyrdom. A Christian took the body, wrapped it in expensive shrouds, and took it to the city of Lydda, his home town, and they built a great church on his name there.", ar: "" } },
      { kind: 'reading', text: { en: "His intercession be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-24",
    title: { en: "Baramouda 24", ar: "24 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Sina, the Soldier.", ar: "استشهاد سنا الجندى رفيق إيسيذيروس" } },
      { kind: 'reading', text: { en: "On this day also, St. Sina, the companion of (1), was martyred. After the Governor of Farma had tortured the two friends and St. Isidore was martyred, he kept St. Sina in the prison until he was removed.", ar: "في مثل هذا اليوم استشهد القديس سنا الجندي رفيق القديس إيسيذروس المذكور في اليوم الثامن عشر من برمهات وذلك أنه بعد ما عذب الاثنان واستشهد إيسيذروس فأبقي سنا في السجن إلى أن عزل والي الفرما وتولي غيره بوصية بأن لا يبقي أحدا ممن يعترف باسم المسيح . ولما سمع بوجود سنا هذا وانه من أكابر الجنود وانه كان قد عذب كثيرا ولم ينثن عن رأيه أمر في الحال بقطع رأسه ونال إكليل الشهادة وكانت أمه بجواره عندما استشهد فرأت نفسه صاعدة كما رأت نفس إيسيذروس وقت استشهاده سابقا . ثم أخذوا جسده وكفنوه ووضعوه مع جسد صديقه القديس إيسيذروس في مدينة سمنود وظهرت منهما عجائب ." } },
      { kind: 'reading', text: { en: "When the new Governor took charge with the command not to keep any one who confessed the Name of Christ, he heard about the presence of Sina in prison, and that he was a captain of soldiers. St. Sina was tortured much but did not turn from his counsel. The Governor immediately ordered to cut off his head and he received the crown of martyrdom. His mother was beside him when he was martyred, and she saw a multitude of angels carrying away his soul as she saw St. Isidore's soul at the time of his martyrdom before.", ar: "صلاتهما تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "They took his body, shrouded it, laid it with the body of his friend St. Isidore in the city of Samanoud, and many signs and wonders appeared from them.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Sinuthius (Shenouda I), 55th Pope of Alexandria.", ar: "نياحة القديس البابا سانوتيوس الأول ال55" } },
      { kind: 'reading', text: { en: "On this day, of the year 596 A.M. (April 19th., 880 A.D.), the great father Pope Sinuthius (Shenouda I), 55th Pope of the See of St. Mark, departed. This holy father was a monk in the monastery of St. Macarius. He advanced in righteousness and worship, and was ordained archpriest for the monastery.", ar: "في مثل هذا اليوم من سنة 596 ش ( 19 أبريل سنة 880 م ) تنيح الأب العظيم البابا سانوتيوس الخامس والخمسون من باباوات الكرازة المرقسية . وهذا القديس كان قد ترهب بدير القديس مقاريوس وإذ تزايد في الفضيلة والعبادة عين قمصا علي كنيسة الدير واختير بعد قليل للبطريركية بتزكية الشعب والأساقفة واعتلي الكرسي في 13 طوبة 575 ش ( 8 يناير سنة 859 م ) فحلت به شدائد كثيرة واضطهادات قاسية . وكان الله يجري علي يديه آيات كثيرة وشفي أمراضا مستعصية ." } },
      { kind: 'reading', text: { en: "Shortly after, he was chosen for the Patriarchate with the recommendation of the people and bishops. He was enthroned on the 575 A.D. (January 8th., 859 A.D.), and great tribulations and severe persecutions befell him. God performed through him many signs and healed many grievous sicknesses.", ar: "وحدث مرة أن امتنع المطر عن مدينة مريوط ثلاث سنوات حتى جفت الآبار وأجدبت الأراضي فجاء هذا الأب إلى كنيسة القديس أبا مينا بمريوط وقام بخدمة القداس وطلب من الله أن يرحم خليقته فلما كان غروب ذلك اليوم بدأت الأمطار تنزل رذاذا ثم انقطعت فدخل هذا الأب إلى مخدعه ووقف يصلي قائلا يا ربي يسوع أرحم شعبك حتى حصلت بروق ورعود ونزل غيث كالسيل المنهمر حتى امتلأت البقاع والكروم والآبار فرويت الأرض وابتهج الناس ممجدين الله صانع العجائب ." } },
      { kind: 'reading', text: { en: "Once there was a drought in the city of Mariout for three years, the wells dried up and the farm land became barren. This father came to the church of St. Mina, celebrated the Divine Liturgy, and supplicated God to have mercy upon His creation. At the setting of the sun of that day, the rain began lightly then ceased. This father entered his room and stood up praying and he said: \"O My Lord Christ, have mercy on Thy people with the riches of Thy compassion, and let them be filled with Thy good pleasure.\" Before he finished his prayer, mighty thunders and lightnings started, and the rain descended like a flood, until the wells, the vineyards, and the farms were filled with water. The people rejoiced, glorifying God the wonder worker.", ar: "وحدث عندما كان هذا الأب بالبرية لزيارة الأديرة أن أغار عربان الصعيد علي الأديرة للقتل والنهب فخرج إليهم وبيده صليبه فحين أبصروا الصليب تقهقروا من أمامه وولوا هاربين (ذكر خبر هذه الأعجوبة تحت اليوم التاسع من شهر برمودة) ." } },
      { kind: 'reading', text: { en: "When this father was in the wilderness visiting the monasteries, the Arabs of Upper Egypt came to the desert of Scetis to plunder the monasteries and kill the monks. The Pope took his staff that had the sign of the cross on it and he went forth to meet them, when they saw the Cross they retreated and fled away. (The account of this wonder is mentioned in the", ar: "وكان بقرية تسمي بوخنسا من قري مريوط قوم يقولون ان المتألم عنا علي عود الصليب هو إنسان فارقه اللاهوت فكتب هذا البابا رسالة أيام الصوم المقدس وأمر بقراءتها في الكنائس قال فيها &quot; ان المتألم عنا هو الله الكلمة بجسده من غير أن يفترق عنه . ولكن الألم لم يقع علي جوهر اللاهوت . كما تضرب الحديد المشتعل نارا فلا تتأثر النار ولكن الأثر يأتي علي الحديد كذلك لكي تكون لآلام الناسوت قيمة كان لابد للاهوت أن يكون حالا فيه وبهذه الآلام كفر المسيح عن البشرية كلها &quot;" } },
      { kind: 'reading', text: { en: "Some men, in a village called Boukhnessa, one of the villages of Mariout, said that He Who suffered for us was only a man and that the Divinity had departed from Him. This Pope wrote a letter and sent it during the Holy Fast (Lent) to be read in all the churches. He said in it, \"God the Word suffered for us in His Body, and His Divinity was not separated from His humanity, not for a twinkling of an eye. The pain and suffering did not touch and affect the Divinity, as when you hammer a red hot iron, the iron suffers from the hammering but not the flame. For the passion of the Humanity to be of value, the Hypostatic union with the Divinity was a must, and through this passion Christ redeemed all the humanity.\"", ar: "وظهر أيضا قوم آخرون قالوا أن طبيعة الناسوت ماتت وكان هؤلاء من البلينا مع أساقفتهم فلما بلغ هذا الأب خبرهم كتب لهم يقول &quot; ان طبيعة الله الكلمة غير المدركة ولا ملموسة ولا متألمة , لا يمكن أن يقع الألم علي جوهرها ولكن اشتراك اللاهوت مع الناسوت في الألم كان اشتراكا أدبيا . ليعطي قيمة لهذه الآلام فتسدد دين البشرية لله غير المحدود ولا يمكن أن يكون هذا إلا إذا كان اللاهوت مشتركا فيها أدبيا بدون أن يتأثر جوهره ولهذا يقال : قدوس الله يا من صلبت عنا ارحمنا &quot;" } },
      { kind: 'reading', text: { en: "Also, some men from the city of El-Balyana, and their bishops, said that the Divine Nature died. When the father heard that, he wrote to them saying: \"The Nature of God, the Word, is unknowable, intangible, and impassable for it was impossible for the pain to affect its essence. The participation of the Divinity with the humanity in passion is moral participation, to give a value to these sufferings, to pay the debt of the humanity to God the Omnipresent, and that would only be possible if the Divinity would participate morally without affecting His essence. So we say \"Holy God, Who was crucified for us, have mercy upon us.\" When his letter reached them, they turned from their error, and the bishops came and confessed the true and right faith before the Pope and asked for forgiveness.", ar: "ولما وصلت رسالته إليهم رجعوا عن ضلالهم واعترف الأساقفة بذلك أمام البابا وطلبوا المغفرة ." } },
      { kind: 'reading', text: { en: "Pope Shenouda I, cared greatly for the churches, their buildings, and their needs. He also cared for the places wherein pilgrims sojourned, and what money has left to him, he gave to the poor and the needy.", ar: "وكان هذا البابا كثير الاهتمام بأمور الكنائس ومواضع الغرباء وكان كل ما يفضل عنه يتصدق به . ولما أكمل سعيه الصالح تنيح بسلام بعد أن أقام علي الكرسي المرقسي إحدى وعشرين سنة وثلاثة أشهر وإحدى عشر يوما صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When he finished his good course, he departed in peace. He stayed on the Chair of for 21 years, 3 months and 11 days.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-25",
    title: { en: "Baramouda 25", ar: "25 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس سارة ووالديها" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهدت القديسة سارة وولداها وهذه كانت من أهل إنطاكية زوجة لرجل اسمه سقراطس أحد قواد دقلديانوس . وكان هذا القائد قد ترك دينه المسيحي تملقا للملك وكان يتظاهر أمام زوجته بأنه إنما فعل هذا خوفا من الملك . ورزقها الله ولدين فلم تستطع أن تعمدهما بإنطاكية خوفا من الملك ومن زوجها . فأخذتهما وسافرت إلى الإسكندرية لتعمدهما هناك . فأراد الله أن يظهر عظم أمانتها منفعة للأجيال المقبلة فأهاج رياحا شديدة كادت تغرق المركب . فخافت المرأة أن يموت ولداها بغير عماد . فصلت صلاة طويلة ثم شرطت ثديها اليمين وأخذت من الدم وصلبت علي جبيني ولديها وقلبهما ثم غطستهما في البحر ثلاث مرات باسم الأب والابن والروح القدس" } },
      { kind: 'reading', text: { en: "", ar: "وبعد ذلك سكتت الرياح وهدأ البحر وسارت المركب ولدي وصولها إلى الإسكندرية دخلت الكنيسة وقدمت ولديها للبابا بطرس خاتم الشهداء ليعمدهما مع أطفال المدينة . فلما أخذ الولدين ليعمدهما جمد ماء المعمودية كالحجر . فتعجب البابا من ذلك فأخذ الولدين مرة ثانية فتجمد الماء ثانية . وهكذا إلى ثلاث مرات فاستغرب البابا واستخبر من والدتهما عن الآمر . فعرفته بما جري لها في البحر وما عملته لولديها فمجد الله قائلا : &quot; حقا أنها معمودية واحدة &quot; ." } },
      { kind: 'reading', text: { en: "", ar: "ولما عادت المرأة إلى إنطاكية أنكر عليها زوجها ما فعلته وأخبر الملك بذلك فاستحضرها ووبخها قائلا : &quot; لماذا ذهبت إلى الإسكندرية لتزني مع النصارى ؟ &quot; فأجابته القديسة : &quot; أن النصارى لا يزنون ولا يعبدون الأصنام ومهما أردت بعد هذا فافعله وسوف لا تسمع مني كلمة أخري &quot; فقال لها : &quot; عرفيني ماذا عملت بالإسكندرية &quot; فلم تجبه . فأمر بشد يديها إلى خلفها ووضع ولديها علي بطنها ثم حرقها بالنار فحولت وجهها إلى الشرق وصلت . ثم أسلمت روحها الطاهرة مع ولديها . ونالوا جميعا إكليل الشهادة ." } },
      { kind: 'reading', text: { en: "", ar: "صلاتهم تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "تذكار القديس ببنوده المتوحد" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم نحتفل بتذكار القديس ببنوده المتوحد والقديس ثاؤذورس العابد ومائة شهيد استشهدوا جميعا ببلاد العجم ." } },
      { kind: 'reading', text: { en: "", ar: "صلواتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Sarah, and her two sons.", ar: "" } },
      { kind: 'reading', text: { en: "On this day, St. Sarah and her two sons, were martyred. She was from the city of Antioch, the wife of a man whose name was Socrates, one of the governors of Emperor Diocletian. This Governor had denied Christ to please Diocletian, pretending before his wife that he did that because of his fear from the Emperor.", ar: "" } },
      { kind: 'reading', text: { en: "Sarah had two sons, she could not baptize in Antioch, because of her fear from the Emperor and her husband. She took them and sailed to Alexandria to baptize them there. God willed to reveal the greatness of her faith as a lesson to the generations to come. God brought forth a great tempest and the ship was about to be wrecked and drown. Sarah was afraid that her sons would be drowned without being baptized. She prayed a long prayer, then she wounded her right breast, took some of her blood, anointed them making the sign of the cross upon the foreheads, and over the hearts. Then she dipped them in the sea three times saying: \"In the Name of the Father and the Son and the Holy Spirit.\"", ar: "" } },
      { kind: 'reading', text: { en: "After that, the winds died down, a great calm came on the sea, and the ship sailed toward Alexandria. When she arrived, took her sons, went to the church, and handed them to Pope Peter, the seal of the martyrs. He baptized them, together with the children of the city. When the Pope carried one of her sons to baptize him, the water froze. The Pope went on baptizing other children and came back to her sons, but the water froze again. The same thing occurred on the third attempt. The Pope was amazed and asked their mother about her story. She told him about all what happened to her at sea and what she did for her sons. He glorified God and said: \"It is indeed one baptism.\"", ar: "" } },
      { kind: 'reading', text: { en: "When the woman returned to Antioch, her husband denounced what she had done. He related what happened to the Emperor accusing his wife with adultery. The Emperor brought her and reproached her saying: \"Why did you go to Alexandria to commit adultery with the Christians?\" The Saint answered him: \"Christians do not commit adultery, and do not worship idols, and after this do what you wish, for you will not hear another word from me.\"", ar: "" } },
      { kind: 'reading', text: { en: "The Emperor asked her: \"Tell me what did you do in Alexandria?\" When she did not answer him, he ordered to tie her hands behind her, and to place her two sons on her belly, and to bum all three of them. She turned her face to the east and prayed. They burnt her, with her sons. She delivered up her pure soul along with her sons, and they all received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of Sts. Babnuda (Paphnute) the hermit, Theodore the worshipper, and the One hundred martyrs.", ar: "" } },
      { kind: 'reading', text: { en: "This day also marks the commemoration of Sts. Babnuda (Paphnute) the hermit, Theodore the worshipper, and the One hundred martyrs, who were martyred in Persia.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-26",
    title: { en: "Baramouda 26", ar: "26 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد سوسيتيوس بن سوسيبطرس" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديس سوسنيوس . كان هذا القديس ابنا لأحد خواص الملك دقلديانوس . وكان قد ظهر له ملاك الرب وقوي عزمه علي نوال إكليل الشهادة . فحفظ هذا الآمر في قلبه وحدث أن أرسله الملك إلى مدينة نيقوميدية لتجديد عبادة الأوثان فحزن هذا القديس جدا واستحضر قسا واستعلم منه عن كل أمور الدين حتى عرف حقائقه ولما علم أبوه بحاله وشي به لدي الملك أنه لا يعبد الأوثان فأمر بتعذيبه فعذبوه بكل نوع من العذاب المريع وكان الرب يقويه ويصبره . وأخيرا قطعوا رأسه ونال إكليل الشهادة . وكان عدد الذين شاهدوه وقت العذاب وأمنوا بسببه ونالوا إكليل الشهادة ألفا ومائة وسبعين شخصا ." } },
      { kind: 'reading', text: { en: "", ar: "صلاتهم تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد البابا يوأنس الاسكندرىال78" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم من سنة 1009 ش ( 21 أبريل سنة 1293 م ) تنيح البابا يؤنس السابع البطريرك الثامن والسبعون . ومن أمره أنه بعد أن رشح أراخنة القاهرة البابا غبريال الثالث للبطريركية واختاروه ورسموه قمصا ، اتفق بعض أراخنة مصر علي يوأنس بن أبي سعيد السكري وعملوا قرعة هيكلية فسحب اسم غبريال فنازعه يوأنس المذكور ومن كان معه فأبطل القرعة وقدم يوأنس في 6 طوبة سنة 978 ش ( أول يناير سنة 1262 م ) بعد وفاة البابا ( أثناسيوس الثالث ) سلفه وأقام بطريركا ست سنين وتسعة شهور وتسعة عشر يوما ثم عزل وتولي مكانه البابا غبريال الثالث من 24 بابه سنة 985 ش إلى 6 طوبه سنة 987 ش ثم عزل غبريال وأعيد يوأنس بأمر السلطان في 7 طوبه ." } },
      { kind: 'reading', text: { en: "", ar: "وفي أيامه أمر السلطان في سنة 980 ش أن يحفروا حفرة كبيرة ويجمعوا النصارى ويحرقوهم فيها . وطلب البطريرك وقرر عليه دفع خمسين آلف دينار وأقاموا سنتين يحصلونها وأعتقوا النصارى الذين جرت عليهم شدائد كثيرة في أيامه . وقاسي الأساقفة تجارب شديدة وتنيح البابا غبريال سلفه في مدة رئاسته الثانية فتقدم عليه في جدول البطاركة واستمر البابا يوأنس علي الكرسي في المدة الثانية اثنين وعشرين سنة وثلاثة شهور وتسعة عشر يوما وتنيح بسلام في 26 برمودة سنة 1009 ش ودفن بالبساتين بدير النسطور ." } },
      { kind: 'reading', text: { en: "", ar: "صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Sousenyos.", ar: "" } },
      { kind: 'reading', text: { en: "On this day, St. Sousenyos was martyred. This Saint was the son of one of the friends of Emperor Diocletian. The angel of the Lord appeared to him and strengthened his heart on receiving the crown of martyrdom, and he kept this in his heart.", ar: "" } },
      { kind: 'reading', text: { en: "The Emperor sent him to the city of Nicomedia to restore the worship of idols. This Saint sorrowed exceedingly. He sent and brought a priest who taught him the doctrine of the church, the facts of the faith and baptized him.", ar: "" } },
      { kind: 'reading', text: { en: "When his father knew that, he accused him to the Emperor that he did not worship the idols. The Emperor ordered to torture him with severe tortures, but the Lord strengthened and comforted him. Finally, they cut off his head, and he received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "The number of those who had seen him during his torture and believed because of him, were eleven hundred and seventy. They were martyred and received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Youannis VII, 78th. Patriarch.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, of the year 1009 A.M. (April 21st, 1293 A.D.), Pope Youannis VII, 78th Patriarch, departed. After the lay leaders of Cairo had nominated Pope Gabriel III for the Papacy, some of the lay leaders of Egypt agreed to choose Youannis Ebn Abi-Saaid El-Soukary. They threw an altar lot which fell on Gabriel, but Youannis, the above mentioned, along with his supporters, quarreled with Gabriel. Youannis nullified the result of the lot and was enthroned in the 978 A.M. (January 15th., 1262 A.D.), after the departure of Pope Athanasius III, his predecessor.", ar: "" } },
      { kind: 'reading', text: { en: "He remained on the Patriarchal Chair six years, nine months, and nineteen days, then he was dismissed. Pope Gabriel took over his place from the 985 A.M. to the 987 A.M., then he was dismissed. Youannis was reinstated by the order of El-Sultan on the .", ar: "" } },
      { kind: 'reading', text: { en: "During Pope Youannis' days, in the year 980 A.M., El-Sultan ordered to dig a huge pit and throw the Christians in it, to be burned. He brought the Patriarch and mandated him to pay fifty thousand Dinars, which took two years to collect. Consequently, they released the Christians who suffered much tribulations in his time, and the bishops suffered much afflictions. Pope Gabriel, his predecessor, departed during Pope Youannis second period of heading the church, so he was listed in the list of the Patriarchs before Youannis.", ar: "" } },
      { kind: 'reading', text: { en: "Pope Youannis remained on the Chair in his second time of heading the church 22 years, 3 months, and 19 days, and departed in peace in the 26th. of Baramoudah 1009 A.M. He was buried in the gardens of El-Nastour monastery.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-27",
    title: { en: "Baramouda 27", ar: "27 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "Martyrdom of St. Boctor Ebn Romanus", ar: "استشهاد بقطر بن رومانيوس" } },
      { kind: 'reading', text: { en: "On this day, which coincided with the 26th. of April 68 A.D., the great apostle St. Mark, the evangelist of the land of Egypt, was martyred. He was the first Pope of Alexandria and one of the Seventy Apostles.", ar: "في مثل هذا اليوم استشهد القديس الجليل بقطر بن رومانوس وزير الملك دقلديانوس . وقد ربته أمه مرتا علي المبادئ المسيحية وارتقي في رتب المملكة حتى أصبح الثالث في مرتبتها . وكان له وقتئذ عشرون سنة وكان كثير الصوم والصلاة وافتقاد المحبوسين وإعانة الضعفاء والمساكين . ولما قطعوا رأس القديسة ثاؤذورا أم القديسين قزمان ودميان لم يجسر أحد أن يدفنها خوفا من الملك . فتقدم هذا القديس وأخذ الجسد وكفنه ثم دفنها غير مبال بأمر الملك ." } },
      { kind: 'reading', text: { en: "His name was John, as the Holy Bible says: \"He came to the house of Mary, the mother of John whose surname was Mark, where many were gathered together praying\" (Acts 12:12). He was the one that the Lord Christ, to Whom is the glory, meant when He said: \"Go into the city to a certain man, and say to him, The Teacher says, My time is at hand; I will keep the Passover at your house with My disciples\" ( 26:18).", ar: "وكثيرا ما كان يبكت والده علي عبادته الأوثان . فوشي به عند الملك فاستحضره وطلب منه أن يعبد الأوثان طاعة للآمر الملكي فحل القديس منطقة الجندية ورماها في وجهه قائلا : &quot; خذ عطيتك التي أعطيتنيها &quot; وألقاها بين يديه ، فأشار أبوه علي الملك أن يرسله إلى الإسكندرية ليعذب فيها وفيما هم سائرون به ودعته أمه باكية فأوصاها علي المساكين والأرامل والمنقطعين . ولما وصل الإسكندرية عذبه الوالي أرمانيوس عذابا كثيرا ثم أرسله إلى والي أنصنا فعذبه هذا أيضا ثم قطع لسانه وقلع عينيه . وكان الرب يقويه ويصبره كل مرة وكانت صبية عمرها خمس عشرة سنة تنظره من شباك منزلها أثناء العذاب فرأت إكليلا نازلا علي رأسه فاعترفت بذلك أمام الوالي والجمع الحاضر فأمر الوالي بقطع رأسها ورأس القديس بقطر , فنالا إكليل الحياة في ملكوت السموات ." } },
      { kind: 'reading', text: { en: "His house was the first Christian church, where they ate the Passover, hid after the death of the Lord Christ, and in its upper room the Holy Spirit came upon them.", ar: "ويوجد حي في الإسكندرية لم يزل للان يعرف باسم البقطرية نسبة لهذا القديس حيث يظهر أنه كانت هناك كنيسة باسمه في هذا الحي ." } },
      { kind: 'reading', text: { en: "This Saint was born in Cyrene (One of the Five Western cities, Pentapolis - in North Africa). His father's name was Aristopolus and his mother's name was Mary. They were Jewish in faith, rich and of great honor. They educated him with the Greek and Hebrew cultures. He was called Mark after they emigrated to Jerusalem, where St. Peter had become a disciple to the Lord Christ. St. Peter was married to the cousin of Aristopolus. Mark visited St. Peter's house often, and from him he learned the Christian teachings.", ar: "صلاتهما تكون معنا ، ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Once Aristopolus and his son Mark were walking near the Jordan river, close by the desert, they encountered a raving lion and a lioness. It was evident to Aristopolus that it would be his end and the end of his Son, Mark. His compassion for his son compelled him to order him to escape to save himself. Mark answered, \"Christ, in whose hands our lives are committed, will not let them prey on us.\" Saying this, he prayed, \"O, Christ, Son of God protect us from the evil of these two beasts and terminate their offspring from this wilderness.\" Immediately, God granted this prayer, and the two beasts fell dead. His father marvelled and asked his son to tell him about the Lord Christ. He believed in the Lord Christ at the hands of his son who baptized him.", ar: "" } },
      { kind: 'reading', text: { en: "After the ascension of the Lord Christ, he accompanied Paul and to preach the Gospel in Antioch, Seleucia, Cyprus, Salamis, and Perga Pamphylia where he left them and returned to Jerusalem. After the Apostolic Council in Jerusalem, he went with Barnabas to Cyprus.", ar: "" } },
      { kind: 'reading', text: { en: "After the departure of Barnabas, with the order of the Lord Christ, St. Mark went to Afrikia, Berka, and the Five Western cities. He preached the Gospel in these parts, and believed on his hands most of its people. From there, he went to Alexandria in the 61 A.D.", ar: "" } },
      { kind: 'reading', text: { en: "When he entered the city, his shoe was torn because of the much walking in preaching and evangelism. He went to a cobbler in the city, called Anianus, to repair it. While he was repairing it the awl pierced his finger. Anianus shouted in Greek saying \"EIS THEOS\" which means \"O, ONE GOD\". When St. Mark heard these words his heart rejoiced exceedingly. He found it suitable to talk to him about the One God. The Apostle took some clay, spat on it and applied it to Anianus' finger, saying in the Name of Jesus Christ the Son of God, and the wound healed immediately, as if nothing happened to it. , who brought the children of Israel out of Egypt, and gave them the Law, the captivity of the children of Israel to Babylon, and the prophecies that foretold the coming of Christ.", ar: "" } },
      { kind: 'reading', text: { en: "Anianus invited him to go to his house and brought to him his children. The Saint preached and baptized them in the Name of the Father and the Son and the Holy Spirit.", ar: "" } },
      { kind: 'reading', text: { en: "When the believers in the Name of Christ increased and the pagan people of the city heard that, they were raged with anger and thought of slaying St. Mark. The faithful advised him to get away for a short while for the sake of the safety of the church and its care. St. Mark ordained St. Anianus a Bishop for Alexandria, three priests and seven deacons. He went to the Five Western Cities, remained there for two years preaching, and ordained bishops, priests, and deacons.", ar: "" } },
      { kind: 'reading', text: { en: "He returned to Alexandria where he found the believers had increased in number, and built a church for them in the place known as Bokalia (The place of cows), east of Alexandria on the sea shore.", ar: "" } },
      { kind: 'reading', text: { en: "It came to pass, when he was celebrating the feast of the Resurrection on the 29th day of Baramudah, year 68 A.D., the same day coincided with the great pagan Celebration for the feast of the god Syrabis, a multitude of them assembled and attacked the church at Bokalia and forced their way in. They seized St. Mark, bound him with a thick rope and dragged him in the roads and streets crying, \"Drag the dragon to the place of Cows.\" They continued dragging him with severe cruelty. His flesh was torn and scattered everywhere, and the ground of the city was covered with his blood. They cast him that night into a dark prison.", ar: "" } },
      { kind: 'reading', text: { en: "The angel of the Lord appeared to him and told him: \"O Mark, the good servant, rejoice for your name has been written in the book of life, and you have been counted among the congregation of the saints.\" The angel disappeared, then the Lord Christ appeared to him, and gave him peace. His soul rejoiced and was glad.", ar: "" } },
      { kind: 'reading', text: { en: "The next morning (30th of Baramudah), the pagans took St. Mark from the prison. They tied his neck with a thick rope and did the same as the day before, dragging him over the rocks and stones. Finally, St. Mark delivered up his pure soul in the hand of God, and received the crown of martyrdom, the apostolic crown, the crown of evangelism, and the crown of virginity.", ar: "" } },
      { kind: 'reading', text: { en: "Nevertheless, St. Mark's death did not satisfy the rage of the pagans and their hatred. They gathered much firewood and prepared an inferno to burn him. A severe storm blew and heavy rains fell. The pagans became frightened, and they fled away in fear.", ar: "" } },
      { kind: 'reading', text: { en: "The believers came and took the holy body, carried it to the church they built at Bokalia, wrapped it up, prayed over him and place it in a coffin. They laid it in a secret place in .", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-28",
    title: { en: "Baramouda 28", ar: "28 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد ميليوس الناسك" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديس ميليوس كان هذا الأب ناسكا ومجاهدا طول أيامه ساكنا مع تلميذيه في مغارة بجبل خوراسان وحدث أن خرج ولدا ملك خوراسان لصيد الوحوش ونصبا شباكهما فوقع هذا القديس داخلها . وكان لابسا ثوبا من الشعر فلما رأياه خافا منه وسألاه قائلين &quot; أمن الإنس أنت أم من الجن ؟ &quot; فأجابهما &quot; &quot; أنا إنسان خاطئ ساكن في هذا الجبل لعبادة الرب يسوع المسيح ابن الله الحي &quot; فقالا له &quot; ليس اله إلا الشمس والنار فقدم الضحايا لهما وإلا قتلناك &quot; فأجابهما : &quot; ان هذه خليقة الله وصنعة البشر وأنتما لا تعرفان الحق . الأفضل لكما أن تعبدا الإله الحقيقي ، خالق هذه كلها &quot; فقالا له : &quot; أتزعم أن المصلوب من اليهود اله &quot; ؟ فقال &quot; نعم ذلك الذي صلب الخطية وأمات الموت هو الإله &quot; فحنق الاثنان عليه وأمسكا تلميذيه وعذباهما ثم قتلاهما . وظلا يعذبان القديس مدة أسبوعين أخيرا وقف أحدهما من خلفه والأخر من الأمام ليضرباه بانشاب ورماه الواحد من هنا والأخر من هناك حتى تنيح بسلام وفي الغد ركضا وراء وحش وضرباه بالنشاب فعاد سهم كل منهما في قلبه فمات الاثنان ." } },
      { kind: 'reading', text: { en: "", ar: "صلاة هذا القديس تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديسة باسالسفوس ومن معها بجبل خورسان" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهاد القديسة باسالسفوس ومن معها بجبل خورسان. صلاتهم تكون معنا و لربنا المجد دائما أبديا أمين ." } },
      { kind: 'heading', text: { en: "The Departure of St. Helena, The Empress.", ar: "" } },
      { kind: 'reading', text: { en: "On this day of 327 A.D., St. Helena the Empress, departed. She was born in the city of Raha (Edessa) for Christian parents about the year 247 A.D. They brought her up in a Christian manner, taught her the doctrine of the church and the religious ethics. She was very beautiful. When \r\nEmperor Constantius the First, Emperor of Byzantium, came to the city of Raha, and heard about this Saint, he sought her out and married her. She gave birth to Constantine who became the first Christian Emperor. She raised him up well, and taught him philosophy, wisdom and knighthood. During the reign of her son, she saw a vision at night as if one said to her: \"Go to Jerusalem and search carefully for the Honorable Cross and the Holy places.\" When she informed her son about this, he sent her with many soldiers to Jerusalem.", ar: "" } },
      { kind: 'reading', text: { en: "She searched for the wood of the \r\nalong with the other two crosses whereon the two thieves were crucified. She wanted to know which was the cross of the Lord Christ. St. Macarius, bishop of Jerusalem, told her that it was the cross that was written on the top of it: \"This is Jesus, king of the Jews.\" She asked him that she wished to see a miracle to make sure that it was the cross of the Lord. By the Will of God, a procession of a dead man was passing by at that time. She placed the other two crosses on the body of the dead man, but he did not rise. When she placed the third cross, straightway the dead rose up. Her faith increased and her joy multiplied. \r\n. She gave the needed money to build the churches to St. Macarius, she took the honorable Cross and the nails and returned to her righteous son \r\n. He kissed the Cross and placed it in a case made of gold and decorated with precious stones, and placed some of the nails in his helmet.", ar: "" } },
      { kind: 'reading', text: { en: "St. Helena led a righteous life, and she endowed many endowments for the churches, monasteries and the poor. She departed at age of eighty.", ar: "" } },
      { kind: 'reading', text: { en: "May her prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Yoannis the Eleventh, the 89th. Patriarch of Alexandra.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also of the year 1168 A.M. (May 4th., 1452 A.D.) Pope Yoannis the eleventh, the 89th. Patriarch of Alexandria, departed. He was known as Yoannis El-Maksi for he was from El-Maksa in Cairo. His name was Farag before his ordination. He was enthroned Patriarch on the , 1143 A.M. (May 11th., 1427 A.D.). He sat on the throne of for 24 years, 11 month, and 23 days. His residence was in the patriarchal cell in Haret Zewala. When he departed, he was buried in the tomb of the monastery of El-Khandak. The Chair remained unoccupied after his departure, for four month and six days. He was contemporary to the rulers El-Ashraf, El-Aziz, El-Zaher, and El-Mansour. He encountered many hardships that required the intervention of the kings of Ethiopia who threatened the Egyptian government to cut the flow of the Nile because of the persecution of El-Nasara (The Copts, the Nazarenes). The Patriarch was forbidden to communicate with the kings of Ethiopia and Nubia without the permission and knowledge of the rulers of the government.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Gabriel the Eighth, the 97th. Patriarch of Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also of the year 1319 A.M. (May 14th., 1603 A.D.), Pope Gabriel the eighth, the 97th. Patriarch of Alexandria, departed during the reign of Sultan Ahmad the first, the Ottoman. He was from Meer, and became a monk in Anba Bishoy monastery in the wilderness of Sheahat (Scetis). His name was Shenouda, and was ordained Patriarch on sunday the 16th day of Baounah 1303 A.M. (June 20th., 1587 A.D.). The enthronement celebration was headed by Anba Zacharias, Bishop of Jerusalem, and Anba Kyrellos El-Khiami, in the church of St. Mercurius in Old Cairo. At the time of his ordination, the Copts were divided, and they chose for themselves four patriarchs, and they deposed him. He returned later on to his Chair at the time of Sultan Mourad the third, the Ottoman and his papacy was confirmed.", ar: "" } },
      { kind: 'reading', text: { en: "It came to pass (As was written in a document in St. Antonios monastery) that he decreed that the fast of the Apostles must start on the 21st. of Baounah until the 5th. of Abib, and that there should be no fasting during the three days of Nineva, the Advent fast should start on the first of Kiahk, and that the fast of the Virgin be left optional. All the Copts at that time approved what he had decreed. However, after his departure, they returned back to the old tradition of fasting.", ar: "" } },
      { kind: 'reading', text: { en: "He departed in the monastery of the Virgin Mary known as El-Sourian, after he had been on the throne of St. Mark for fifteen years, ten month, and twenty four days.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramouda-29",
    title: { en: "Baramouda 29", ar: "29 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Erastus, the Apostle.", ar: "نياحة أرسطوس الرسول" } },
      { kind: 'reading', text: { en: "On this day, St. Erastus, one of the Seventy Apostles, departed. He received the grace of the holy spirit in the upper room of Zion with the Disciples. He preached, ministered, and suffered along with them frequently.", ar: "في مثل هذا اليوم تنيح القديس أرسطوس الرسول كان هذا القديس من السبعين رسولا وقبل نعمة الروح المعزي مع الرسل في عليه صهيون . وتكلم معهم باللغات وخدم وكرز وتألم معهم مرارا كثيرة ثم وضعوا عليه اليد ورسموه أسقفا علي أورشليم . وقد علم فيها وفي غيرها وأجري الله علي يديه آيات كثيرة منها تحويل المياه المالحة إلى عذبه وجاهد مع بولس الرسول في رحلاته العديدة حيث كان خادما له وهو الذي ورد ذكره في الإصحاح التاسع عشر من سفر أعمال الرسل . وبعد أن بلغ سن الشيخوخة تنيح بسلام . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "They laid the hands on him, and ordained him bishop for Jerusalem. He taught there and in many other places, and God worked great signs and wonders on his hands. As example he changed bitter salty water to sweet water.", ar: "" } },
      { kind: 'reading', text: { en: "He labored with St. Paul the apostle in his many journeys, for he ministered unto him. He is mentioned in chapter nineteen of the Acts of the Apostles. After he reached a good old age, he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Acacius, Bishop of Jerusalem.", ar: "نياحة القديس أكاكيوس أسقف أورشليم ومن معه" } },
      { kind: 'reading', text: { en: "On this day also, St. Acacius, Bishop of Jerusalem, departed. He was a pure and righteous man. He was persecuted for a long time, and God wrought many signs and wonders by his hands, then departed in peace.", ar: "في مثل هذا اليوم تنيح القديس أكاكيوس أسقف أورشليم وكان قد نشأ بارا ، واضطهد زمانا طويلا وأجري الله علي يديه آيات وعجائب ثم تنيح بسلام" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "صلاته معنا . ولربنا المجد دائما . آمين" } }
    ],
  },
  {
    id: "synax-baramouda-30",
    title: { en: "Baramouda 30", ar: "30 برموده" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of the Great Saint Mark, the Apostle The Evangelist of the Land of Egypt.", ar: "استشهاد مارمرقس الرسول اول باباوات الاسكندرية" } },
      { kind: 'reading', text: { en: "On this day, which coincided with the 26th. of April 68 A.D., the great apostle St. Mark, the evangelist of the land of Egypt, was martyred. He was the first Pope of Alexandria and one of the Seventy Apostles.", ar: "في مثل هذا اليوم الموافق 26 أبريل سنة 68 م استشهد الرسول العظيم القديس مرقس كاروز الديار المصرية وأول باباوات الإسكندرية وأحد السبعين رسولا كان اسمه أولا يوحنا كما يقول الكتاب : أن الرسل كانوا يصلون في بيت مريم أم يوحنا المدعو مرقس (أع 12 : 12) وهو الذي أشار إليه السيد المسيح له المجد بقوله لتلاميذه : &quot; أذهبوا إلى المدينة إلى فلان وقولوا له . المعلم يقول وقتي قريب وعندك أصنع الفصح مع تلاميذي (مت 26 : 18) &quot; ولقد كان بيته أول كنيسة مسيحية حيث فيه أكلوا الفصح وفيه اختبأوا بعد موت السيد المسيح وفي عليته حل عليهم الروح القدس" } },
      { kind: 'reading', text: { en: "His name was John, as the Holy Bible says: \"He came to the house of Mary, the mother of John whose surname was Mark, where many were gathered together praying\" (Acts 12:12). He was the one that the Lord Christ, to Whom is the glory, meant when He said: \"Go into the city to a certain man, and say to him, The Teacher says, My time is at hand; I will keep the Passover at your house with My disciples\" ( 26:18).", ar: "ولد هذا القديس في ترنا بوليس (من الخمس مدن الغربية بشمال أفريقيا) من أب اسمه أرسطو بولس وأم أسمها مريم . إسرائيلي المذهب وذي يسار وجاه عريض ، فعلماه وهذباه بالآداب اليونانية والعبرانية ولقب بمرقس بعد نزوح والديه إلى أورشليم حيث كان بطرس قد تلمذ للسيد المسيح . ولأن بطرس كان متزوجا بابنة عم أرسطو بولس فكان مرقس يتردد علي بيته كثيرا ومنه درس التعاليم المسيحية ." } },
      { kind: 'reading', text: { en: "His house was the first Christian church, where they ate the Passover, hid after the death of the Lord Christ, and in its upper room the Holy Spirit came upon them.", ar: "وحدث أن أرسطو بولس وولده مرقس كانا يسيران بالقرب من الأردن وخرج عليهما أسد ولبؤة وهما يزمجران فخاف أبوه وأيقن بالهلاك ودفعته الشفقة علي ولده أن يأمره بالهروب للنجاة بنفسه ولكن مرقس طمأنه قائلا لا تخف يا أبي فالمسيح الذي أنا مؤمن به ينجينا منهما . ولما اقتربا منهما صاح بهما القديس قائلا &quot; السيد المسيح ابن الله الحي يأمركما أن تنشقا وينقطع جنسكما من هذا الجبل &quot; فانشقا ووقعا علي الأرض مائتين فتعجب والده وطلب من ابنه أن يعرفه عن المسيح فأرشده إلى ذلك وآمن والده وعمده بالسيد المسيح له المجد ." } },
      { kind: 'reading', text: { en: "This Saint was born in Cyrene (One of the Five Western cities, Pentapolis - in North Africa). His father's name was Aristopolus and his mother's name was Mary. They were Jewish in faith, rich and of great honor. They educated him with the Greek and Hebrew cultures. He was called Mark after they emigrated to Jerusalem, where St. Peter had become a disciple to the Lord Christ. St. Peter was married to the cousin of Aristopolus. Mark visited St. Peter's house often, and from him he learned the Christian teachings.", ar: "وبعد صعود السيد المسيح استصحبه بولس وبرنابا للبشارة بالإنجيل في إنطاكية وسلوكية وقبرص وسلاميس وبرجة بمفيلية حيث تركهما وعاد إلى أورشليم وبعد انتهاء المجمع الرسولي بأورشليم استصحبه برنابا معه إلى قبرص ." } },
      { kind: 'reading', text: { en: "Once Aristopolus and his son Mark were walking near the Jordan river, close by the desert, they encountered a raving lion and a lioness. It was evident to Aristopolus that it would be his end and the end of his Son, Mark. His compassion for his son compelled him to order him to escape to save himself. Mark answered, \"Christ, in whose hands our lives are committed, will not let them prey on us.\" Saying this, he prayed, \"O, Christ, Son of God protect us from the evil of these two beasts and terminate their offspring from this wilderness.\" Immediately, God granted this prayer, and the two beasts fell dead. His father marvelled and asked his son to tell him about the Lord Christ. He believed in the Lord Christ at the hands of his son who baptized him.", ar: "وبعد نياحة برنابا ذهب مرقس بأمر السيد المسيح إلى أفريقية وبرقة والخمس المدن الغربية . ونادي في تلك الجهات بالإنجيل فآمن علي يده أكثر أهلها . ومن هناك ذهب إلى الإسكندرية في أول بشنس سنة 61 م وعندما دخل المدينة انقطع حذاؤه وكان عند الباب إسكافي أسمه إنيانوس ، فقدم له الحذاء وفيما هو قائم بتصليحه جرح المخراز إصبعه فصاح من الألم وقال باليونانية &quot; اس ثيؤس &quot; ( يا الله الواحد ) فقال له القديس مرقس : &quot; هل تعرفون الله ؟ &quot; فقال &quot; لا وإنما ندعو باسمه ولا نعرفه &quot; . فتفل علي التراب ووضع علي الجرح فشفي للحال ، ثم أخذ يشرح له من بدء ما خلق الله السماء والأرض فمخالفة آدم ومجيء الطوفان إلى إرسال موسى وإخراج بني إسرائيل من مصر وإعطائهم الشريعة وسبي بابل ثم سرد له نبوات الأنبياء الشاهدة بمجيء المسيح فدعاه إلى بيته وأحضر له أولاده فوعظهم جميعا وعمدهم باسم الأب والابن والروح القدس ." } },
      { kind: 'reading', text: { en: "After the ascension of the Lord Christ, he accompanied Paul and to preach the Gospel in Antioch, Seleucia, Cyprus, Salamis, and Perga Pamphylia where he left them and returned to Jerusalem. After the Apostolic Council in Jerusalem, he went with Barnabas to Cyprus.", ar: "ولما كثر المؤمنون باسم المسيح وسمع أهل المدينة بهذا الآمر جدوا في طلبه لقتله . فرسم إنيانوس أسقفا وثلاثة قسوس وسبعة شمامسة ثم سافر إلى الخمس المدن الغربية وأقام هناك سنتين يبشر ويرسم أساقفة وقسوسا وشمامسة ." } },
      { kind: 'reading', text: { en: "After the departure of Barnabas, with the order of the Lord Christ, St. Mark went to Afrikia, Berka, and the Five Western cities. He preached the Gospel in these parts, and believed on his hands most of its people. From there, he went to Alexandria in the 61 A.D.", ar: "وعاد إلى الإسكندرية فوجد المؤمنين قد ازدادوا وبنوا لهم كنيسة في الموضع المعروف ببوكوليا ( دار البقر ) شرقي الإسكندرية علي شاطئ البحر وحدث وهو يحتفل بعيد الفصح يوم تسعة وعشرين برمودة سنة 68 م وكان الوثنيون في اليوم نفسه يعيدون لألههم سرابيس ، أنهم خرجوا من معبدهم إلى حيث القديس قبضوا عليه وطوقوا عنقه بحبل وكانوا يسحبونه وهم يصيحون &quot; جروا الثور في دار البقر &quot; فتناثر لحمه وتلطخت أرض المدينة من دمه المقدس وفي المساء أودعوه السجن فظهر له ملاك الرب وقال له &quot; افرح يا مرقس عبد الإله ، هودا اسمك قد كتب في سفر الحياة وقد حسبت ضمن جماعة القديسين &quot; وتواري عنه الملاك ثم ظهر له السيد المسيح وأعطاه السلام فابتهجت نفسه وتهللت &quot; ." } },
      { kind: 'reading', text: { en: "When he entered the city, his shoe was torn because of the much walking in preaching and evangelism. He went to a cobbler in the city, called Anianus, to repair it. While he was repairing it the awl pierced his finger. Anianus shouted in Greek saying \"EIS THEOS\" which means \"O, ONE GOD\". When St. Mark heard these words his heart rejoiced exceedingly. He found it suitable to talk to him about the One God. The Apostle took some clay, spat on it and applied it to Anianus' finger, saying in the Name of Jesus Christ the Son of God, and the wound healed immediately, as if nothing happened to it., who brought the children of Israel out of Egypt, and gave them the Law, the captivity of the children of Israel to Babylon, and the prophecies that foretold the coming of Christ.", ar: "وفي اليوم التالي ( 30 برمودة ) أخرجوه من السجن وأعادوا سحبه في المدينة حتى أسلم روحه الطاهرة ولما أضرموا نارا عظيمة لحرقه حدثت زلازل ورعود وبروق وهطلت أمطار غزيرة فارتاع الوثنيون وولوا مذعورين . وأخذ المؤمنون جسده المقدس إلى الكنيسة التي شيدوها وكفنوه وصلوا عليه وجعلوه في تابوت ووضعوه في مكان خفي من هذه الكنيسة ." } },
      { kind: 'reading', text: { en: "Anianus invited him to go to his house and brought to him his children. The Saint preached and baptized them in the Name of the Father and the Son and the Holy Spirit.", ar: "صلاة هذا القديس العظيم والكاروز الكريم تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "When the believers in the Name of Christ increased and the pagan people of the city heard that, they were raged with anger and thought of slaying St. Mark. The faithful advised him to get away for a short while for the sake of the safety of the church and its care. St. Mark ordained St. Anianus a Bishop for Alexandria, three priests and seven deacons. He went to the Five Western Cities, remained there for two years preaching, and ordained bishops, priests, and deacons.", ar: "" } },
      { kind: 'reading', text: { en: "He returned to Alexandria where he found the believers had increased in number, and built a church for them in the place known as Bokalia (The place of cows), east of Alexandria on the sea shore.", ar: "" } },
      { kind: 'reading', text: { en: "It came to pass, when he was celebrating the feast of the Resurrection on the 29th day of Baramudah, year 68 A.D., the same day coincided with the great pagan Celebration for the feast of the god Syrabis, a multitude of them assembled and attacked the church at Bokalia and forced their way in. They seized St. Mark, bound him with a thick rope and dragged him in the roads and streets crying, \"Drag the dragon to the place of Cows.\" They continued dragging him with severe cruelty. His flesh was torn and scattered everywhere, and the ground of the city was covered with his blood. They cast him that night into a dark prison.", ar: "" } },
      { kind: 'reading', text: { en: "The angel of the Lord appeared to him and told him: \"O Mark, the good servant, rejoice for your name has been written in the book of life, and you have been counted among the congregation of the saints.\" The angel disappeared, then the Lord Christ appeared to him, and gave him peace. His soul rejoiced and was glad.", ar: "" } },
      { kind: 'reading', text: { en: "The next morning (30th of Baramudah), the pagans took St. Mark from the prison. They tied his neck with a thick rope and did the same as the day before, dragging him over the rocks and stones. Finally, St. Mark delivered up his pure soul in the hand of God, and received the crown of martyrdom, the apostolic crown, the crown of evangelism, and the crown of virginity.", ar: "" } },
      { kind: 'reading', text: { en: "Nevertheless, St. Mark's death did not satisfy the rage of the pagans and their hatred. They gathered much firewood and prepared an inferno to burn him. A severe storm blew and heavy rains fell. The pagans became frightened, and they fled away in fear.", ar: "" } },
      { kind: 'reading', text: { en: "The believers came and took the holy body, carried it to the church they built at Bokalia, wrapped it up, prayed over him and place it in a coffin. They laid it in a secret place in .", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of this great Saint and honorable Evangelist be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  }
];
